function _mEsc(s) {
  return String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

function _manualSecciones() {
  return [
    { icon: '🧭', titulo: 'La barra de arriba', desc: 'Es igual en todos los módulos: mismo lugar para cada cosa y el color de la moneda del módulo (el mismo del Hub).',
      pasos: ['A la izquierda, la moneda y el nombre del módulo. En la computadora, tocando el nombre (POS ▾) se abre la lista para pasar a otro módulo; al final de esa lista está «Volver al Hub».', 'Al lado van los apartados (Vender, Comprobantes, Remitos, Pedidos, Etiquetas, Vales, Promociones, Online, Caja, Ajustes): son íconos; al pasar el mouse aparece el nombre, y el apartado en el que estás queda marcado en blanco con su nombre.', 'A la derecha: el tamaño de letra (A− / A+), ↺ Volver a lo normal y Salir.', 'En el celular: los apartados están adentro del botón ☰; a la vista quedan 🏠 Hub (volver al Hub) y Salir.', '¿Dudas? Preguntale a Clodi (el botón de abajo a la derecha): sabe todo lo que dice este manual.'] },
    { icon: '↩', titulo: 'Nota de crédito sin factura asociada', desc: 'La nota de crédito se puede hacer con o sin factura asociada. Asociarla es lo mejor cuando existe (devolución de una venta del POS); sin asociar sirve para un descuento bancario, un ajuste o la devolución de una factura que no está en el POS (por ejemplo una del Dragonfish).',
      pasos: ['Con factura: pastilla Nota de crédito, buscás la factura por número o cliente y entran sus renglones; la nota sale con la misma letra y el mismo cliente, y no puede devolver más de lo que queda.', 'Sin factura: pastilla Nota de crédito y no elegís ninguna factura. Cargás el cliente como en una venta (define si es B o A) y los renglones: productos del buscador (si vuelve mercadería, sube el stock) o «＋ Agregar un concepto sin mercadería» para un descuento o ajuste: escribís el concepto y el importe, y no mueve stock.', 'Después elegís cómo se le devuelve la plata (efectivo, vale de cambio, etc.) y emitís. Igual que siempre, la nota de crédito necesita la autorización de la encargada o la cajera.', 'Sin factura asociada no hay devolución automática por el Point: la devolución a la tarjeta se hace desde la terminal.', 'A ARCA la nota sin factura se informa con el período (del día 1 del mes a la fecha) en lugar del comprobante asociado.'] },
    { icon: '🔎', titulo: 'Cobros por Mercado Pago: se verifican antes de emitir', desc: 'Cuando el cliente paga por transferencia a la cuenta de Mercado Pago, con el Point o el QR «No integrado», o con un link de pago, el POS busca ese cobro en la cuenta antes de emitir la factura. Ya no hace falta entrar a Tesorería a mirar las transferencias: la consulta es la misma y la hace el POS.',
      pasos: ['Elegí el medio (Transferencia, Point o QR en «No integrado», Link de pago) y poné el importe exacto que pagó el cliente.', 'Cuando el cliente avisa que ya pagó, tocá «Verificar» (o directamente Emitir: verifica primero). El POS consulta la cuenta cada pocos segundos, hasta dos minutos.', 'Cuando el cobro aparece queda el tilde verde «está en Mercado Pago» con el día y la hora, el código queda anotado como referencia y, si el ticket está pagado completo, la factura se emite sola.', 'Si hay más de un cobro por el mismo importe, muestra la lista para elegir cuál es (mirá la hora y el código del comprobante del cliente).', 'Cada cobro sirve para un solo comprobante: una vez usado no vuelve a aparecer. La transferencia queda además marcada como reclamada en Tesorería.', 'Si no aparece (demora de Mercado Pago, o el cliente transfirió a otra cuenta): «Sin verificar» deja emitir con la autorización de la encargada o la cajera, y queda registrado.', 'Qué busca: transferencia = lo que entró a la cuenta en las últimas 24 horas; Point y QR no integrados = cobros de este local de las últimas 3 horas; link = pagos sin local de las últimas 3 horas. Siempre por importe exacto.', 'En Oficina funciona igual, pero como la venta online se cobra primero y se factura después, busca el cobro hasta 15 días para atrás: al tocar Emitir lo encuentra solo y emite. Si el cobro entró por otra cuenta (el banco, u otra cuenta de Mercado Pago) no lo va a ver: ahí va «Sin verificar».', 'No aplica en notas de crédito, remitos ni presupuestos. El Point integrado no lo necesita: ya confirma solo.'] },
    { icon: '🔗', titulo: 'Link de pago de Mercado Pago desde el POS', desc: 'El link de pago se arma desde el mismo ticket, sin entrar a Mercado Pago: el POS lo genera por el importe, lo manda por WhatsApp y después verifica solo si el cliente pagó.',
      pasos: ['Cargá los artículos y el cliente. En la forma de pago elegí «Link de pago» y dejá el importe (viene el total).', 'Tocá «Generar link». Aparece una pastilla con el importe, «vence en 48 h» (y «cobra de verdad» si el POS está en prueba), la casilla del WhatsApp del cliente (viene cargado si lo tiene en la ficha) y tres íconos: el verde de WhatsApp abre el chat con el mensaje y el link listos; el de copiar copia el link (pasando el mouse por arriba se ve); la cruz cierra.', 'El renglón queda con la marca «link generado». El link vence a las 48 horas y sirve para un solo pago por ese importe.', 'Cuando el cliente avisa que pagó, tocá «¿Pagó?» (o Emitir). El POS le pregunta a Mercado Pago por ese link en particular, no por importe: no se confunde con otro cobro. Si está pago, la factura se emite sola.', 'Si todavía no pagó, avisa y se puede volver a consultar las veces que haga falta. «Link» reabre la ventana del link; la cruz lo descarta (por ejemplo para cambiar el importe).', 'Si el cliente pagó con un link armado a mano en Mercado Pago: «Verificar» lo busca por importe, como antes.', 'Ojo: el link cobra de verdad aunque el POS esté en modo prueba, igual que el Point.'] },
    { icon: '⏳', titulo: 'CAI de los remitos: vencimiento y aviso', desc: 'El CAI es el código que ARCA autoriza para los remitos R. Desde el 25-nov-2026 no se usan más talonarios de imprenta: los remitos salen por sistema con el CAI de autoimpresor, uno solo para los puntos de venta 37 (Alcorta), 38 (Unicenter) y 39 (Oficina). No tiene rango de números: cada punto de venta arranca en 1 (00037-00000001, 00038-00000001, 00039-00000001) y sigue. Dura 180 días. En Ajustes → «CAI de los remitos» está la lista con el punto de venta, el CAI, por qué número va, el vencimiento y cuántos días faltan. Los CAI de imprenta viejos (puntos de venta 1, 14 y 31) quedan en la lista como «Ya no se usa».',
      pasos: ['El sistema revisa los vencimientos todos los días a las 9: desde 30 días antes de que venza les llega un aviso al celu a los admin una vez por semana, y la última semana todos los días, hasta que se cargue el nuevo. Es un solo aviso para los tres puntos de venta.', 'Para renovarlo: ARCA con clave fiscal → Autorización de Impresión de Comprobantes (abre Factuweb) → Claudia Adorno S.R.L. → Autoimpresor → Nueva Solicitud de CAI, para el REMITO R y los puntos de venta 37, 38 y 39. ARCA lo da en el momento, pero solo si el informe mensual de remitos está al día (ver «Informe mensual de remitos a ARCA»).', 'Cuando está el CAI nuevo, un admin entra a Ajustes → «CAI de los remitos» → «Cargar el nuevo» en cualquiera de los tres puntos de venta y pone el número y el vencimiento: el POS lo pasa solo a los otros dos, porque el CAI nuevo reemplaza al anterior en los mismos puntos de venta. Ahí se apaga el aviso. La numeración sigue donde iba: no vuelve a 1.', 'Si un punto de venta ya no se usa, se destilda «En uso» y no molesta más.', 'El POS no entra solo a ARCA (necesita la clave fiscal): los datos son los que se cargan acá. El remito que emite el POS es un remito R con el CAI de su local: toma de esta lista el punto de venta y el vencimiento, y numera solo. Si el local no tiene un CAI vigente, el POS no deja emitir remitos reales hasta que se cargue el nuevo; cuando faltan 30 días, avisa al emitir.', 'En modo prueba los remitos salen con el punto de venta 9999 y sin CAI: no usan los números de verdad.'] },
    { icon: '📋', titulo: 'Informe mensual de remitos a ARCA', desc: 'Como autoimpresor, la empresa tiene que informarle a ARCA todos los meses el último número de remito R que usó en cada punto de venta (RG 3665, art. 29). Según esa norma se hace hasta el día 15 del mes siguiente (conviene confirmar el plazo con el estudio). Si no se informa, ARCA no da el CAI nuevo cuando vence el que hay.',
      pasos: ['En Ajustes → «Informe mensual de remitos a ARCA» se elige el mes (viene puesto el mes anterior).', 'La tabla muestra, por punto de venta (37 Alcorta, 38 Unicenter, 39 Oficina), cuántos remitos se hicieron ese mes, del número al número, y el último número: ese es el que se informa. Los anulados también cuentan, porque usaron su número. Los de prueba no cuentan.', 'Se informa en ARCA con clave fiscal: Autorización de Impresión de Comprobantes (abre Factuweb) → Claudia Adorno S.R.L. → Menú Principal → Autoimpresor → Régimen de Información. Ahí hay dos formas: «Carga Manual Web» (a mano) o «Importación de datos» (con un archivo). Qué campos pide cada una todavía no está relevado.', 'Cuando ya se informó, un admin toca «Ya lo informé en ARCA» y queda marcado con quién y cuándo.', 'Los días 2, 9 y 13 de cada mes, si falta informar el mes anterior, les llega un recordatorio al celu a los admin con los números.', 'Un punto de venta que no hizo remitos en el mes aparece como «Sin remitos ese mes».'] },
    { icon: '🏢', titulo: 'Facturar con la sucursal Oficina desde un local', desc: 'Hoy esto está habilitado solo para Unicenter. Alcorta no puede facturar con la sucursal Oficina (no le aparece Oficina en el selector de local), porque mientras factura por debajo del mínimo del alquiler no tiene sentido desviar facturas a Oficina; cuando haga falta, un admin lo vuelve a habilitar. En un local habilitado, las chicas pueden facturar con la sucursal Oficina eligiéndola arriba, en el selector de local. Con Oficina elegida, el local solo puede facturar: tiene Vender (factura y nota de crédito), Comprobantes y Vales. No puede hacer remitos, presupuestos, comprobantes manuales ni movimientos de stock de Oficina, y no ve Pedidos, Etiquetas ni la Caja de Oficina; para todo eso vuelve a su local en el selector. Facturando con Oficina (desde la propia Oficina o desde Unicenter eligiendo Oficina arriba) aparece además la forma de pago «Cuenta corriente», que no existe facturando con el local: es solo para Oficina. Esa factura sale con el punto de venta y el stock de Oficina, pero la venta se le computa al local que la hizo.',
      pasos: ['El POS anota solo de qué local es la venta: mira el usuario que está abierto (el genérico de Alcorta = Alcorta). No hay que cargar nada.', 'En Comprobantes de Oficina esas facturas llevan la marca violeta «venta de Alcorta» (o del local que sea).', 'Un local que entra a la sucursal Oficina ve en Comprobantes solo lo que emitió ese local (y los traslados que Oficina le manda): los comprobantes propios de Oficina y los del otro local no le aparecen.', 'En la planilla de ventas van a la columna «Fc Oficina» del local, no a las ventas de Oficina. Una nota de crédito sobre esa factura sigue al mismo local.', 'Si la factura la hace alguien de Oficina o un admin con la sucursal Oficina, es venta de Oficina.'] },
    { icon: '📊', titulo: 'Cruce del POS con la planilla de ventas', desc: 'El POS arma solo lo que va a la planilla de ventas de cada local (Alcorta, Unicenter, Oficina), con las mismas columnas que la planilla. En Ajustes → «Planilla de ventas · cruce con el POS» (solo admin) se ve el cálculo de cualquier día y, debajo, lo que hoy tiene cargado la planilla para comparar.',
      pasos: ['Facturas A y B (menos las notas de crédito): se reparten por forma de pago. Efectivo y dólares → Efectivo; Point, QR y link → QR / MP; transferencia → Transferencia; vale o gift card → Vales; cuenta corriente → Cta. cte.', 'Comprobantes X (factura manual) → columna Online, y su parte en efectivo es el «efectivo negro» de la planilla.', 'Facturas que un local hizo con la sucursal Oficina → columna «Fc Oficina» de ese local. No cuentan como venta de Oficina.', 'Remitos y presupuestos no son venta: no entran. Los comprobantes anulados y los de prueba tampoco.', 'Mientras el POS esté en modo prueba, o el cruce esté apagado, NO se carga nada en la planilla: solo se ve el cálculo. Cuando se pase a real y se active, se carga solo cada 15 minutos.', 'El pase nunca pisa un día ya controlado ni una fila que cargó el Dragonfish.'] },
    { icon: '🗒', titulo: 'Registro: quién hizo y quién autorizó', desc: 'En Ajustes → «Registro · quién hizo y quién autorizó» (solo admin) queda todo lo que pasa en el POS con la hora exacta: cada comprobante emitido (factura, nota de crédito, remito, presupuesto), cada anulación, cada movimiento de stock manual y cada pedido de autorización, también los rechazados o los que no se usaron.',
      pasos: ['Columna «Quién»: la persona que lo hizo y cómo lo supo el POS: «cámara» (la reconoció), «eligió su nombre» (a mano) o «su usuario» (entró con su usuario personal). Si fue con el usuario genérico del local, lo aclara.', 'Columna «Autorizó»: quién autorizó y por qué camino: cámara, celular o usuario y clave.', 'Se filtra por fechas y por local, y el buscador encuentra por persona, número de comprobante o artículo. El ojo abre el comprobante.', 'Sirve para cruzar con las cámaras del local: la hora está con segundos.'] },
    { icon: '🗣', titulo: 'Pedirle a Clodi que arme una venta', desc: 'A Clodi se le puede pedir que deje cargado un ticket: por ejemplo «haceme una factura con el código SMINI por 1, en efectivo» o «armame un presupuesto con RECTOGR3 por 4 y SRECTO por 2». Clodi busca los códigos, carga los artículos con sus cantidades en Vender y, si le dijiste la forma de pago, la deja puesta por el total.',
      pasos: ['Clodi solo PREPARA: te muestra el resumen con el total y el ticket queda cargado en pantalla para revisar.', 'Si tocás «Enviar» en el cartel de Clodi es lo mismo que tocar Emitir: el POS sigue con lo de siempre (cliente, quién emite, autorización si hace falta). Si tocás «Cancelar», el ticket queda cargado para que lo sigas a mano.', 'Los artículos se piden por código. Si un código no existe en el local, Clodi avisa cuál y no carga nada. Si falta stock, lo avisa en el resumen.', 'Formas de pago que entiende: efectivo, dólares, Point, QR, link de pago, transferencia y vale. El cliente y los descuentos se cargan a mano.'] },
    { icon: '🟥', titulo: 'Carteles rojos de error', desc: 'Los carteles rojos de error ya no se cierran solos: quedan en pantalla hasta tocar la ✕, para que nadie se los pierda.',
      pasos: ['Cada cartel rojo tiene una ✕ para cerrarlo a mano.', 'Si el mismo error se repite, no se apilan: el cartel muestra ×2, ×3. Hay como máximo 4 a la vez.', 'Los errores de la base, de internet o del navegador salen explicados en castellano simple; «Ver detalle técnico» muestra el texto original por si hay que pasárselo a quien da soporte.', 'Los carteles verdes de «listo» se siguen cerrando solos.'] },
    { icon: '👁️', titulo: 'Modo «Ver como» (solo administración)', desc: 'Desde el Hub, JP puede entrar al POS viendo lo que ve otra cuenta, para revisar que los permisos hayan quedado bien. Es solo para mirar: no se modifica nada. Arriba queda el cartel «Viendo como … · solo lectura · Salir».',
      pasos: ['Se ven las solapas, los botones y los datos que ve esa cuenta.', 'Si esa cuenta necesitaría permiso para algo (nota de crédito, efectivo, precio del envío…), se abre la ventana de autorización con la lista real de quién podría autorizar. No lee la cara, y «pedir al celu» y «autorizar con clave» solo avisan lo que harían, sin mandar nada.', '«¿Quién emite?» no aparece en ese modo.', 'Al llegar al final de Emitir avisa «hasta acá llegaría …» y no emite: no sale ningún comprobante, nada va a ARCA ni a la impresora, y el cobro con el Point de Mercado Pago no se dispara.', 'Cualquier otro botón que guarde algo avisa «es solo para mirar».'] },
    { icon: '🙈', titulo: 'Apartados ocultos desde el Hub', desc: 'En el Hub → Permisos → Perfiles, cada apartado del POS (Vender, Mercadería, Vales, Caja y ajustes, Otros locales) tiene un interruptor para mostrarlo u ocultarlo entero a un perfil, sin tocar sus funciones una por una.',
      pasos: ['Vender apagado: no se ven las solapas Vender ni Comprobantes.', 'Mercadería apagado: no se ven Remitos, Pedidos ni Etiquetas.', 'Vales apagado: no se ve la solapa Vales. Caja y ajustes apagado: no se ven Caja ni Ajustes.', 'Otros locales apagado: el perfil no ve ni opera los otros locales.', 'Para los perfiles comunes, un apartado oculto tampoco se puede usar ni autorizar: la traba está en la base.', 'Para Clau es distinto: solo se le esconden las solapas; sigue pudiendo autorizar todo cuando le piden permiso.', 'El cambio se toma la próxima vez que esa persona abre o recarga el POS.'] },
    { icon: '🎙️', titulo: 'Clodi: mantener apretado para hablar', desc: 'El micrófono de Clodi ya no se corta solo: se habla mientras se lo mantiene apretado.',
      pasos: ['Mantener apretado el micrófono con el dedo, con el clic del mouse o con la barra espaciadora, y hablar.', 'Al soltar, lo que se dijo se manda solo.', 'En el iPhone (y el iPad) el micrófono abre el teclado: se dicta con el 🎤 del teclado y se manda con retorno.', 'Si no escuchó nada, Clodi lo avisa para volver a probar.'] },
    { icon: '✅', titulo: 'Verificación del mail y del WhatsApp del cliente', desc: 'Para que el comprobante no rebote, el POS revisa el mail o el WhatsApp del cliente al cargarlo y otra vez al tocar Emitir. Si está mal, la casilla queda en rojo con «revisar» y no deja emitir hasta corregirlo.',
      pasos: ['Mail mal escrito (sin arroba, con espacios, sin terminación): avisa y no lo guarda.', 'Errores típicos como «gmial.com», «hotmial.com» o «gmail.con»: propone el correcto y, si se acepta, lo corrige solo.', 'Dominio que no existe o que no recibe mails: avisa «el dominio no existe o no recibe mails». Para eso consulta por internet solo lo que va después de la arroba; si no hay internet, no traba.', 'También revisa el mail que el cliente ya tenía guardado en su ficha de antes.', 'Si el cliente no tiene otro mail: borrar la casilla. El comprobante sale sin mail («sale sin mail») y la ficha del cliente no se toca.', 'WhatsApp: tiene que ser el código de área y el número, 10 números en total, sin 0 ni 15 (ej. 11 1234 5678). Si viene con 0, 15 o +54 9, lo acomoda solo. Para un número de otro país, escribirlo con + y el código del país.', 'La verificación ataja los errores de escritura; no puede saber si la casilla existe de verdad dentro de un dominio válido (por ejemplo, un nombre mal escrito en gmail.com).'] },
    { icon: '🏷️', titulo: 'Cambiar el precio de un artículo: lo autoriza la encargada', desc: 'En el ticket, el precio de cada artículo viene de la lista. En los locales, si se escribe otro precio, el POS pide la autorización de la encargada (o de un admin); la cajera y la vendedora no pueden autorizarlo. En Oficina cambiar el precio es libre para todos. El precio cambiado vale solo para ese comprobante (factura, nota de crédito o presupuesto): no modifica el precio de lista del artículo.',
      pasos: ['Al cambiar el precio de un renglón aparece el pedido de autorización: la cámara reconoce a la encargada, o se le pide al celular, o pone su usuario y clave.', 'Si no se autoriza, el renglón vuelve al precio que tenía.', 'Volver a poner el precio de lista no pide nada.', 'La autorización vale unos minutos: si pasa el tiempo o se cambian más precios, se pide una sola vez más al tocar Emitir, con el detalle de todos los cambios (artículo, precio de lista y precio puesto).', 'No se pide en la nota de crédito, al modificar una factura, ni por lo que viene de un presupuesto, un remito o una seña con el precio que ya traía.', 'Si el POS avisa «Precio distinto al de lista» sin que nadie lo haya cambiado, es que la lista se actualizó: recargar el POS para traer los precios al día.', 'Quién puede cambiar precios sin pedir permiso se maneja en el Hub → Permisos → POS → Vender → «Cambiar el precio de un artículo».'] },
    { icon: '％', titulo: 'Descuentos: los autoriza la cajera o la encargada', desc: 'En los locales, un comprobante con descuento por renglón o con descuento general pide la autorización de la cajera o de la encargada (o de un admin). En Oficina los descuentos son libres.',
      pasos: ['Se carga el descuento como siempre, en la casilla Dto del renglón o en «Descuento general».', 'Al tocar Emitir, el POS pide la autorización una sola vez, mostrando cuánto se descuenta en total: la cámara reconoce a la cajera o a la encargada, o se le pide al celular, o pone su usuario y clave.', 'Si quien está logueada es cajera o encargada con su propio usuario, no pide nada.', 'No se pide en la nota de crédito, al modificar una factura, ni al facturar un presupuesto o un remito con el descuento que ya traía. Si ahí se agranda el descuento, sí.', 'Quién puede descontar sin pedir permiso se maneja en el Hub → Permisos → POS → Vender → «Hacer descuentos».'] },
    { icon: '🏷', titulo: 'Descuentos: quién y hasta cuánto', desc: 'El descuento por artículo y el general los ven todos (también el usuario genérico del local y la vendedora), pero en los locales solo se emiten con la autorización de alguien que tenga el descuento habilitado (la cajera o la encargada) o de un admin. En Oficina el descuento está libre (genéricos y administrativos).',
      pasos: ['Cada perfil tiene un TOPE de descuento que se configura en el Hub → Permisos → Perfiles → POS, en la función «Descuentos»: al lado de Habilitada / Pide permiso / Oculta está la pastilla «hasta __ %» (se pinta cuando tiene valor). Por ejemplo la cajera hasta el 20 % y la encargada hasta el 50 %.', 'La casilla del tope: vacía = sin tope. Va de 0 a 100, acepta decimales con coma («15,5») o «30 %». Se guarda al salir de la casilla o con Enter; Escape la deja como estaba. Los admin y los perfiles con «todo habilitado» dicen «sin tope»; si la función está Oculta para el perfil, la casilla no aparece. El tope es el máximo que ese perfil puede hacer o autorizar.', 'Se mide el mayor descuento que recibe un artículo del comprobante, sumando el suyo y el general: 10 % en un artículo más 20 % general da 28 % en ese artículo.', 'Al pedir la autorización solo aparecen las personas cuyo tope llega a ese %. Si la cámara reconoce a alguien que no llega, avisa «autoriza descuentos hasta el 20 %» y hay que pedírselo a otra.', 'Si la cajera emite sola un descuento que pasa su tope, el POS le pide la autorización de alguien con más rango.', 'Al emitir, la base vuelve a controlar el tope de quien autorizó: si no alcanza, no deja emitir y dice hasta cuánto autoriza.'] },
    { icon: '％', titulo: 'Promociones automáticas en Vender', desc: 'Las promociones cargadas en el apartado Promociones se aplican solas en el ticket: no hay que tocar nada. Los renglones de los artículos que participan de una promo se pintan de color (también el que se paga en un 2x1) y llevan una pastilla con el nombre de la promo; en la columna Dto va el descuento que le hace a ese artículo. Abajo, «Subtotal sin promociones», después «Promociones aplicadas» con cada promo, cuántos artículos y cuánto descuenta (y el ahorro total si hay más de una), y el TOTAL.',
      pasos: ['Se recalculan solas cada vez que se agrega o saca un artículo, se cambia una cantidad o un precio, o se elige la forma de pago (las promos por forma de pago, como «15 % en efectivo», valen cuando todo el ticket se paga con ese medio).', 'Si dos promociones tocan el mismo artículo, se aplica la que más le conviene al cliente. Cada artículo lleva una sola promo de artículos; las promos por monto de compra o por forma de pago se calculan sobre lo que no tiene otra promoción.', 'Un artículo en promoción no lleva otro descuento: la casilla Dto queda fija. Con promociones en el ticket no va el descuento general (se esconde); a los artículos que no están en promo sí se les puede hacer descuento por renglón (con su autorización, como siempre).', 'El descuento de una promoción no pide autorización: lo da el sistema.', 'Al tocar Emitir el POS vuelve a mirar las promociones; si cambió algo (por ejemplo venció en ese momento), avisa «Cambiaron las promociones del ticket» para revisar el total antes de emitir. La base controla igual que el descuento sea el de la promo vigente.', 'La comandera, la hoja A4 y el PDF del mail muestran en cada renglón el nombre de la promoción y cuánto descontó.', 'No se aplican en notas de crédito, señas, gift cards ni al modificar una factura.'] },
    { icon: '📦', titulo: 'Me piden: embalar menos de lo pedido', desc: 'En Pedidos → «Me piden», al abrir un pedido se ve la ficha con el número, de qué local, quién lo pidió, cuándo y la nota. Cada artículo tiene: lo que piden, lo que hay acá según el sistema, la casilla «Embalo» y los botones Embalado / No hay.',
      pasos: ['Si hay todo: tocar «✔ Embalado» (va con la cantidad pedida).', 'Si no hay todo: escribir en «Embalo» las que se mandan (por ejemplo 3 de 6): queda embalado con esa cantidad y aparece «faltan 3». Con 0 queda «No hay».', 'No se puede embalar más de lo pedido.', 'El remito sale con lo embalado (las cantidades de la casilla). Lo que no se mandó no viaja: el local ve en su pedido «mandaron 3» y en «Qué falta» le vuelve a aparecer lo que le sigue faltando.', '«Marcar todo embalado» marca lo que falta ver con la cantidad pedida.'] },
    { icon: '🎨', titulo: 'Un solo diseño para todas las hojas A4', desc: 'La factura, la nota de crédito, el comprobante manual, el presupuesto, el remito, el traslado y el pedido de mercadería salen con el mismo diseño: el fondo de madera, la columna clara de la izquierda con el logo y los datos, y la hoja blanca con los artículos. El diseño está en un solo archivo (a4.css): si se cambia, cambian todas las piezas juntas, tanto el PDF como la «Hoja A4» que se ve en la pantalla.',
      pasos: ['El PDF del pedido (desde el 18-nov) tiene ese mismo diseño: a la izquierda a quién se le pide, dónde entregarlo, quién lo pidió y a quién consultar; a la derecha «Pedido de mercadería» con el número, la versión, la fecha y la hora, y los artículos con el código, la descripción y la cantidad. Al final, las unidades totales.', 'Los pedidos largos siguen en varias hojas, con «continúa en la hoja…» y «Hoja 1 de N».'] },
    { icon: '📋', titulo: 'Pedidos hechos: la lista', desc: 'La lista de pedidos hechos muestra el número, a quién, el estado y los botones. Los artículos no se ven en la lista: se abren tocando el número del pedido (también se puede buscar por artículo en «Buscar»).',
      pasos: ['Debajo del estado van dos íconos: el sobre es el mail y el logo de WhatsApp es el WhatsApp. En verde: ya salió. En gris: todavía no. El sobre en rojo: el mail no salió (pasando el mouse por arriba dice por qué).', 'A la derecha de cada pedido: el PDF, el ícono verde de Excel (baja el pedido en Excel) y el logo de WhatsApp (abre el WhatsApp con el pedido).', 'Si un pedido recibido llegó distinto de lo pedido, al lado dice «con diferencias»: el detalle se ve tocando el número del pedido.', 'Al tocar el número se abre la ficha del pedido: arriba, en celeste, el número y el estado; a quién se le pidió, la fecha y la hora, quién lo pidió (la persona que lo armó) y si salieron el mail y el WhatsApp; la nota si tiene. Abajo los artículos y, como íconos, el PDF y el Excel.', 'Todas las tablas del POS tienen los renglones en colores alternos (blanco y celeste clarito), para seguirlos sin perderse. Al bajar por una tabla larga, la fila de títulos (Artículo, Stock, Mínimo…) queda fija arriba, debajo de la barra del POS.'] },
    { icon: '🚚', titulo: 'Pedidos a Familia García: pendiente, en tránsito y recibido', desc: 'Del otro lado nadie «levanta» el pedido en el sistema: Familia García prepara el Excel y emite su remito o factura. Cuando administración carga ese remito en el Dragonfish, el POS lo cruza solo con el pedido (en menos de un minuto), artículo por artículo.',
      pasos: ['Pendiente de entrega (amarillo): el pedido salió y Familia García todavía no lo facturó.', 'En tránsito (violeta): ya está cargado el remito de Familia García. Al lado se ve el número de remito, la fecha y cuántos artículos no vinieron o vinieron distinto. Al abrir el pedido, la columna «Remito» muestra lo que vino de cada artículo: en rojo si vino menos o no vino, en amarillo si vino de más.', 'Lo que no vino (Familia García no tenía stock) se libera: vuelve a aparecer en «Qué falta» para el próximo pedido. Lo que sí vino cuenta como «pedido» en «Qué falta» hasta 3 días después del remito, para no volver a pedirlo mientras viaja.', 'Recibido (verde): cuando llegan las cajas, en Mercadería → Remitos → «En tránsito» aparece el pedido con el número de remito de Familia García: tocar «Recibir». Se abre la lista con lo que dice el remito ya puesto en «Llegó»: si algo llegó distinto, se corrige ahí y queda registrado para reclamarlo. El stock sigue entrando por el Dragonfish, como hasta ahora.', 'El cruce es por SKU: si hay dos pedidos abiertos con el mismo artículo, el remito se le asigna primero al más viejo. Si Familia García lo manda en dos remitos, se suman. Lo que el remito trae y no se pidió por el POS no se toca. Los renglones «Varios» (sin código) no se cruzan.', 'Una vez en tránsito ya no se puede descontar del pedido (Familia García ya lo facturó).'] },
    { icon: '🔢', titulo: 'Pedidos: «se pide desde» para el chiquitaje', desc: 'Hay mercadería chica que no conviene pedir si son pocas unidades (por ejemplo, menos de 6). A cada artículo se le puede poner «Pedir desde»: si lo que falta no llega a esa cantidad, en «Qué falta» queda en gris y no se marca con «Marcar todos», así no hay que borrarlo a mano del pedido.',
      pasos: ['Se carga en la columna «Pedir desde», al lado del mínimo: está en «Qué falta» (se escribe ahí mismo, en el renglón del artículo) y en «Mínimos». Vacío o 1 = se pide siempre. Es por local, como el mínimo, y pide la misma autorización. Desde el 20-nov se cambian varios y se guardan todos juntos con «Guardar N cambios» del título de la tabla (ver «Mínimos y pedir desde: cambiar varios y guardar todo junto»).', 'En «Qué falta», el artículo muestra «se pide desde 6». Si falta menos que eso, el renglón queda en gris con la pastilla en amarillo.', '«Marcar todos» saltea los grises. Si igual se lo quiere pedir, se tilda a mano y listo.', 'Arriba de la lista se ve cuántos no llegan a la cantidad para pedir.', 'Los artículos que vienen en juego (desglose) no se saltean: se piden o no como un solo artículo.'] },
    { icon: '✏️', titulo: 'Mínimos y «pedir desde»: cambiar varios y guardar todo junto', desc: 'Desde el 20-nov los mínimos y el «pedir desde» ya no se guardan renglón por renglón (antes, con el usuario del local, cada renglón abría la cámara de «¿Quién lo está haciendo?»). Ahora se cambian todos los que haga falta y se guardan juntos, con una sola pregunta de quién lo hace y una sola autorización.',
      pasos: ['En «Qué falta» o en «Mínimos», escribí el número nuevo en la casilla Mínimo o Pedir desde y pasá a la siguiente (Enter baja a la de abajo, como en Excel).', 'El artículo que cambiaste se pinta de amarillo y sube arriba de todo de la tabla, debajo del cartel «N cambios sin guardar», con lo que tenía antes («mínimo antes 5»). Así, subiendo, se ven juntos todos los cambios que hiciste. En «Qué falta» se recalcula enseguida cuánto falta.', 'Si volvés a poner el número que tenía, deja de estar pendiente.', 'En el título de la tabla, que queda siempre fijo arriba aunque bajes, aparece «Guardar N cambios». Al tocarlo se pregunta una sola vez quién lo está haciendo y, si hace falta, se le pide una sola autorización a la encargada o la cajera: en el celu le llega cuántos son y cuáles. Se guardan todos juntos: si uno falla, no se guarda ninguno y quedan pendientes.', '«Descartar», al lado, tira todos los cambios sin guardar (también en las otras compus del local) y vuelven los números de antes.', 'Lo que no guardaste queda preguardado, como los pedidos: si se cierra la ventana, se corta la luz o la sigue otra chica en otra compu del mismo local, al volver a «Qué falta» o «Mínimos» los cambios siguen ahí, pendientes. La pastilla «Mínimos» tiene un puntito naranja mientras haya cambios sin guardar.', 'Si quien está logueada es encargada, cajera o admin, no pide autorización: solo hay que tocar «Guardar N cambios».'] },
    { icon: '🧾', titulo: 'Pedidos: la ficha antes de enviar y las planillas en colores alternos', desc: 'Al tocar para enviar un pedido aparece la ficha «Pedido a Familia García · Unicenter» con «Versión 1» arriba a la derecha, los artículos con su cantidad, la nota y los botones Cancelar y Enviar pedido. Debajo de la nota, una línea chica dice a qué mail va (y la copia).',
      pasos: ['Los artículos van en renglones de colores alternos (blanco y celeste clarito) para seguirlos sin perderse. Lo mismo en todas las planillas de Pedidos: qué falta, mínimos, pedidos hechos, lo que piden los locales y el descuento.', 'La cantidad se cambia en su casilla; la cruz saca el artículo.', 'El destino no se cambia en la ficha: el pedido va al proveedor con el que se armó (lo que se armó en Familia García va a Familia García). Para pedirle a otro, se arma desde su pastilla en «Qué falta».', 'La versión arranca en 1. Si después se descuenta algo de ese pedido, sale la versión 2 con el pedido completo actualizado.'] },
    { icon: '📎', titulo: 'Pedidos: el Excel va adjunto y cada archivo lleva su versión', desc: 'El pedido se manda por mail con el PDF y el Excel adjuntos, y por WhatsApp con un link para bajar el Excel al final del mensaje. El Excel tiene tres columnas y nada más, en este orden: SKU, Descripción y Cantidad, para que el proveedor lo pase directo a su sistema. Los archivos se llaman con el número del pedido y la versión, por ejemplo Pedido_ALC-00003_v1_ClaudiaAdorno.xlsx.',
      pasos: ['Al armar el pedido (o desde la lista, con el botón de WhatsApp) aparece una pastilla con el título del pedido, la casilla del número y dos botones del mismo tamaño: «Copiar» y el de WhatsApp (el ícono verde). El mensaje (título y link) no se muestra; «Copiar» lo copia.', 'Si el número es de un contacto conocido, en la casilla aparece el nombre (por ejemplo «Rivera» para Oficina o «Víctor» para Familia García) en verde. Al pasar el mouse o tocar la casilla aparece el número, por si se lo quiere cambiar; al salir vuelve el nombre. Los nombres se cargan en la agenda de WhatsApp del POS (pedírselo a administración).', 'A Familia García el número viene siempre con el de Víctor. Para mandarlo a otro, tocar la casilla del número y cambiarlo (se pone amarilla); para Oficina y Espalma viene el último número que se usó.', 'Tocar el botón de WhatsApp: se abre el chat de la sucursal con un mensaje corto: el título del pedido (número y local), debajo «Enviado por» con el nombre de quien lo armó (la persona que se identificó con la cara o con la autorización) y «Excel del pedido:» con el link. El mail al proveedor también dice quién lo envía, y el PDF lo pone en «Pidió». El detalle de los artículos no va en el mensaje: está en el Excel. Quien lo recibe toca el link y se le baja el Excel. Anda igual desde la compu y desde el celular, y sale del WhatsApp de siempre del local.', 'En un iPhone o iPad se abre para compartir con el Excel adjunto directamente.', 'Si el link no se pudo armar (por ejemplo, sin internet en ese momento), el Excel se baja a la carpeta Descargas y hay que adjuntarlo a mano en el chat (clip 📎 → Documento).', 'Versiones: todo pedido sale como v1. Si la sucursal lo modifica (hoy, con un descuento sobre un pedido ya enviado), sale la versión siguiente del mismo pedido (Pedido_ALC-00003_v2, v3, etc.) con el pedido COMPLETO ya actualizado: el original menos todo lo descontado hasta ahí. Reemplaza a la versión anterior. El PDF dice «actualizado», la versión al lado del número y qué se descontó; el mail y el WhatsApp también lo aclaran.', 'Los renglones «Varios» (sin código) van con SKU «VARIOS» y lo que se pidió en la Descripción.', 'Desde el 25-nov-2026 el link de cada pedido y de cada factura lleva al final un código al azar (por ejemplo …_ClaudiaAdorno_3f9c…xlsx), para que nadie pueda abrir los de otros locales o los de otras clientas cambiando los números. El archivo que se baja o va adjunto sigue con el nombre de siempre. Los links de facturas mandados antes de esa fecha ya no abren: se vuelve a mandar desde Comprobantes. Los links de pedidos mandados antes andan hasta el 25-dic-2026; después, si alguien necesita uno viejo, se vuelve a mandar desde la lista de pedidos.'] },
    { icon: '🧲', titulo: 'Cobro del Point o del QR que quedó sin facturar', desc: 'Si se cobró con Mercado Pago Point integrado (o con QR con importe), el pago salió aprobado y la factura no llegó a emitirse (se cerró el ticket, se recargó la página, se trabó algo), el cobro no se pierde ni hay que cobrar de nuevo.',
      pasos: ['Armar otra vez el ticket con los mismos artículos y el mismo total.', 'En la forma de pago elegir «Mercado Pago Point» en Integrado (o «Mercado Pago QR» en Integrado) y tocar el botón de cobrar como siempre.', 'Antes de mandar nada a la terminal, el POS avisa: «Hay un cobro de $ … aprobado el … a las … que quedó sin facturar. ¿Lo uso para este ticket?». Aceptar: el renglón queda con el tilde verde de pagado y se emite la factura.', 'Si se contesta que no, cobra de nuevo.', 'Busca cobros del mismo local, por el mismo importe exacto, de las últimas 48 horas, que no estén usados en otra factura ni devueltos.', 'No sirve buscarlo como «No integrado» con el botón Verificar: ese botón busca solo cobros hechos a mano en la terminal, no los que mandó el POS.'] },
    { icon: '👀', titulo: 'Una sola mirada a la cámara para los pasos seguidos', desc: 'Cuando el POS necesita la cámara varias veces seguidas (por ejemplo: autorizar un precio, después «quién emite» y después autorizar el efectivo), alcanza con que reconozca a la persona una vez. La lectura vale un ratito y los pasos siguientes no vuelven a abrir la cámara.',
      pasos: ['Si la cámara reconoció a alguien hace menos de 2 minutos, «quién emite» toma a esa persona sin abrir la cámara de nuevo (avisa «Emite …»).', 'Si reconoció a alguien hace menos de un minuto y medio, la autorización siguiente se resuelve con esa misma lectura, siempre que esa persona tenga permiso para autorizar eso.', 'Pasado ese tiempo, vuelve a mirar.', 'Si la cámara no abre, «quién emite» dice el motivo arriba de los nombres (cámara bloqueada en Chrome, ocupada, tardó demasiado) y se sigue eligiendo el nombre a mano.', 'La autorización de un precio vale unos 8 minutos: si se tarda más en cobrar y emitir, al tocar Emitir la pide otra vez.', 'La cámara nunca deja la pantalla trabada: mira como mucho unos segundos y, si no abre, no da imagen o no reconoce a nadie, pasa sola a la ventana para elegir el nombre o pedir la autorización por el celular o con clave.'] },
    { icon: '🟨', titulo: 'La casilla activa se pinta de amarillo', desc: 'En todo el POS, la casilla donde está parado el cursor (donde se va a escribir) se pinta de amarillo suave con un borde ámbar. Sirve para ver de un vistazo en qué casilla se está: el buscador, el cliente, la cantidad, el precio, el descuento, el pago, la observación o cualquier casilla de una ventana.',
      pasos: ['Al tocar o hacer clic en una casilla, o al pasar a ella con Tab, se pone amarilla.', 'Al salir de la casilla vuelve a su color normal.', 'Si una casilla está en rojo porque tiene un dato para revisar (por ejemplo un mail mal escrito), sigue en rojo aunque el cursor esté ahí.'] },
    { icon: '⚙️', titulo: 'Elegir el Point y el QR con el que se cobra', desc: 'Cada computadora, tablet o celular guarda qué terminal Point y qué QR usa para cobrar. Lo elige cualquier usuario, también el genérico del local, sin pedir permiso y sin entrar a Ajustes. Queda siempre el último que se usó en ese equipo.',
      pasos: ['En Vender, elegir como forma de pago «Mercado Pago Point» o «Mercado Pago QR».', 'Si ese equipo todavía no tiene nada elegido, aparece el botón «Elegí el Point de esta caja» (o «Elegí el QR de esta caja»).', 'Para cambiar de Point o de QR cuando ya hay uno elegido: mantener apretado el botón de cobrar (medio segundo, con el dedo o con el mouse). En vez de cobrar, abre el selector. Un toque corto cobra en el que ya estaba elegido. El engranaje chico de al lado hace lo mismo.', 'Si el botón está apagado porque falta el importe, mantenerlo apretado no hace nada: usar el engranaje o poner primero el importe.', 'Se abre la ventana «Point y QR de esta caja»: tocar la terminal Point que se va a usar y el QR del cartel que el cliente tiene delante. Listo.', 'El botón de cobrar dice siempre a qué Point o a qué QR va el cobro: mirarlo antes de tocar, sobre todo cobrando desde el celular, que se mueve de una caja a otra.', 'La elección queda guardada en ese equipo hasta que se cambie: la próxima vez viene el último que se usó.', 'Si algún día se quiere que pida autorización de un admin, se cambia en el Hub → Permisos → POS → Caja y ajustes → «Elegir el Point y el QR de la caja».'] },
    { icon: '🔳', titulo: 'QR integrado: el cliente escanea y le aparece el importe', desc: 'Con Mercado Pago QR en «Integrado», el POS manda el importe al QR fijo de la caja, igual que hacía el Dragonfish. El cliente escanea el QR con Mercado Pago (o con la app de su banco o billetera) y ve el monto ya cargado: no tiene que escribir nada.',
      pasos: ['Cada local tiene dos QR. En Ajustes → «Mi QR en esta caja» se elige a cuál manda el importe esta computadora: tiene que ser el del cartel que el cliente tiene delante. Queda guardado en esa compu; si no se elige, usa el de la Point de esa caja. El botón de cobrar dice a qué QR va.', 'En la forma de pago elegir «Mercado Pago QR», dejarlo en «Integrado» y poner el importe.', 'Tocar «QR con importe · (caja)». Aparece el cartel en pastilla «Que el cliente escanee el QR de la caja…», con el importe y el botón para cancelar.', 'El cliente escanea el QR impreso de esa caja y paga. El cartel se cierra solo con «Pago aprobado por QR» y el renglón queda con el tilde verde «pagado por QR». Recién ahí se puede emitir.', 'El cobro vence a los 5 minutos si nadie paga; se puede cortar con «Cancelar el cobro».', 'El botón «Verificar» sigue al lado, por si el cliente ya pagó escaneando el QR sin que se le mande el importe: busca el cobro por importe, como en «No integrado».', 'Devolución: la nota de crédito de esa factura trae el medio elegido y devuelve la plata sola por Mercado Pago, igual que con el Point.', 'Ojo: cobra de verdad aunque el POS esté en modo prueba. Y mientras el Dragonfish siga en uso, no mandar un cobro al QR de una caja que en ese momento está cobrando por el Dragonfish.'] },
    { icon: '↩️', titulo: 'Nota de crédito de una venta cobrada por link, QR, Point no integrado o transferencia: la devolución sale sola', desc: 'Si la factura se cobró por Mercado Pago y el cobro quedó verificado en el POS (link de pago, QR, Point no integrado o transferencia), al elegirla para la nota de crédito la forma de pago ya viene en ese mismo medio, con el cartel verde «se devuelve por Mercado Pago al emitir».',
      pasos: ['En Vender → Nota de crédito, buscar la factura y elegirla. La forma de pago viene sola.', 'Si se devuelve una parte, sacar o bajar los renglones que no vuelven: se devuelve solo ese importe.', 'Tocar Emitir (pide la autorización de la nota de crédito, como siempre). Sale la nota de crédito y el POS le pide la devolución a Mercado Pago: aparece «Devolución de $ … hecha por Mercado Pago». La plata vuelve al medio con el que pagó el cliente.', 'Si Mercado Pago no acepta la devolución, el POS avisa en rojo «La nota de crédito salió, pero la plata NO se devolvió» con el motivo: en ese caso hay que devolverla a mano desde Mercado Pago. Puede pasar con una transferencia, que Mercado Pago no siempre deja devolver por este camino.', 'Si la venta se había emitido con autorización, sin verificar el cobro, el POS no sabe qué pago devolver: la devolución se hace desde Mercado Pago.', 'Para devolver de otra forma (efectivo, vale), cambiar la forma de pago antes de emitir: ahí no se devuelve nada por Mercado Pago.'] },
    { icon: '↩️', titulo: 'Nota de crédito de una venta cobrada con Point: la devolución sale sola', desc: 'Si la factura se cobró con Mercado Pago Point integrado, al elegirla para la nota de crédito la forma de pago ya viene en «Mercado Pago Point» con el cartel verde «se devuelve por Mercado Pago al emitir».',
      pasos: ['En Vender → Nota de crédito, buscar la factura y elegirla.', 'Dejar la forma de pago en Mercado Pago Point (viene sola). Si se devuelve solo una parte, sacar o bajar los renglones que no vuelven: el importe se ajusta.', 'Tocar Emitir (pide la autorización de la nota de crédito, como siempre). Sale la nota de crédito y el POS le pide la devolución a Mercado Pago: aparece «Devolución de $ … hecha por Mercado Pago».', 'La plata vuelve al mismo medio con el que pagó el cliente; no hace falta la terminal ni la tarjeta.', 'Si se prefiere devolver de otra forma (efectivo, vale), se cambia la forma de pago antes de emitir.', 'Si la venta no se cobró con Point integrado, la devolución a la tarjeta se hace desde la terminal.'] },
    { icon: '🚚', titulo: 'Envío: el importe lo pone quien vende', desc: 'El artículo ENVIO (gastos de envío) es de precio variable: es el flete que se le cobra al cliente y viene sin importe. Lo carga y le pone el importe cualquier usuario, también el genérico del local, sin pedir autorización.',
      pasos: ['En Vender, buscar «envío» y agregarlo: entra un renglón sin importe.', 'Escribir el importe del flete. No pide autorización.', 'Si algún día se quiere volver a pedir permiso para esto, se cambia en el Hub → Permisos → POS → Vender → «Poner el precio del envío».'] },
    { icon: '🔐', titulo: 'Autorizaciones: cámara, celular o clave', desc: 'Quién puede hacer cada cosa se maneja desde el Hub, no desde el POS: Hub → ícono de persona → Permisos. En «Perfiles» cada función del POS queda Habilitada, Pide permiso u Oculta para cada perfil (vendedora, cajera, encargada, cuenta del local, oficina); en «Personas» se elige el perfil de cada una y su local o sus locales. Habilitada: la hace sola. Pide permiso: la ve, pero al usarla pide la autorización de alguien que la tenga habilitada en ese local. Oculta: no la ve o el POS no la deja. Autoriza una persona con su propio usuario (o un admin); las cuentas genéricas del local o de la oficina nunca autorizan. La lista «pedir al celu» muestra solo a quienes pueden autorizar esa operación en ese local. Las funciones que se manejan así: vender y facturar, facturar como Oficina, emitir sin verificar el cobro, cobrar en efectivo, nota de crédito, remito (son dos permisos separados: se puede habilitar uno sin el otro), presupuesto rojo (comprobante X), anular un comprobante, vales y gift cards, anular un vale, recibir traslados, movimiento de stock a mano, pedidos, marcar lo que piden los otros locales («Me piden»), devolver la card física de una gift card, mínimos, etiquetas, caja, ajustes, ver otros locales y operar en otros locales. En la Oficina: las notas de crédito y los remitos los hacen y los autorizan Contreras y Rivera con su usuario personal (perfil «administrativa»); Iván (perfil «depósito») hace remitos solo, pero para una nota de crédito pide autorización. Si una persona tiene varios locales, elige en cuál está trabajando con el selector de arriba y el POS recuerda el último. Cómo quedó cargado hoy (desde el 13 de noviembre): en el local todos facturan desde la cuenta genérica del local, que ve todo el POS. La factura la hace cualquiera desde la cuenta genérica sin pedir autorización cuando la forma de pago es integrada o está verificada; queda anotado quién la emitió y quién atendió al cliente. Lo que pide permiso de cajera para arriba (cajera, encargada o admin): notas de crédito, cobrar en efectivo, hacer pedidos (y descontar, recibir o cancelar un pedido), remitos, el presupuesto rojo (comprobante X, que implica cobrar en efectivo: lleva una sola autorización), anular un comprobante, cambiar mínimos y emitir sin verificar un cobro de Mercado Pago. Los movimientos de stock (movimiento manual, anular un movimiento, recibir o rechazar mercadería en tránsito) los autoriza solo la encargada o un admin. Factura y forma de pago: la factura se emite sola si el sistema verificó el pago, es decir, que es así en dos casos. Uno: Point integrado, cuando la terminal avisa que el cobro se aprobó (aparece «✔ pagado»); la base vuelve a comprobarlo al emitir: que el cobro esté aprobado en Mercado Pago, que sea de ese local, por ese importe, y que no se haya usado ni devuelto. Dos: transferencia, QR de Mercado Pago, Point o QR no integrados y link de pago, después de tocar «Verificar» y que el cobro aparezca en la cuenta de Mercado Pago. Un Point integrado que no llegó a cobrar, o un cobro que no aparece al verificar, solo se emite con autorización. La cuenta corriente (solo Oficina) no pide autorización porque no es un cobro en el momento. Si el pago no está verificado (efectivo en pesos o en dólares, o un cobro de Mercado Pago que no aparece al verificar: transferencia, QR, Point o link), emitirla pide autorización de cajera para arriba. Vale para las cuentas genéricas y para cualquier usuario sin rango. La traba está en la base, no solo en la pantalla: sin pago verificado y sin una autorización válida la factura no se crea y no se le pide el CAE a ARCA, y en el comprobante queda anotado quién autorizó y cómo. Quien entra con su propio usuario de cajera, encargada o admin no necesita pedirla: emite sola. Mientras el reconocimiento por cara esté apagado, la autorización se pide al celular o con usuario y clave; la cámara no se abre. Con el reconocimiento prendido los caminos son tres, en este orden. En todos queda anotado quién autorizó y cómo.',
      pasos: ['1) Cámara: lee sola y en segundo plano, sin mostrarse: solo aparece «Un momento…» y después «Autorizado por …». Si quien está frente a la caja es la encargada o la cajera del local (o un admin) y tiene la cara registrada, queda autorizado al instante con su nombre, sin mandar nada al celu. Para los movimientos de stock tiene que ser la encargada o un admin.', 'Si la cámara reconoce a alguien que no tiene ese permiso en el Hub, avisa que eso lo autoriza la encargada o la cajera y pasa al camino 2. Quién puede autorizar con la cara es lo mismo que la lista de la ventana y la clave: los permisos del Hub (desde el 18-nov; antes la cámara miraba el rango viejo de RRHH y rechazaba, por ejemplo, a una cajera cargada como empleada). Si no reconoce a nadie en unos 7 segundos, también. Con «Pedir al celu o con clave» se saltea la cámara.', '2) Pedir al celu: la ventana «Pedir autorización» muestra una pastilla con el APELLIDO de cada persona que puede autorizar (si dos comparten apellido, se agrega la inicial del nombre), todas del mismo tamaño. Las de quienes están en el local ahora (según el reloj y los turnos) van primero y rellenas de color; las de quienes están afuera van solo con borde, y se les puede pedir igual porque autorizan desde donde estén. Una pastilla gris con borde punteado, con el apellido y abajo, en chiquito, «sin avisos», es alguien que puede autorizar pero no tiene los avisos activados en el celu: no se le puede mandar el pedido, así que autoriza mirando a la cámara o con su usuario y clave (al tocarla, la ventana lo explica). Los avisos se activan desde el celu, en la app de Colaboradores. Al tocar una pastilla «Pedir a …», le llega la notificación para aceptar o rechazar. Si la cámara no anduvo o no reconoció a nadie, la ventana lo dice arriba en rojo, con el motivo: «Chrome tiene la cámara bloqueada para el POS» (se arregla tocando el candado de la barra de direcciones → Cámara → Permitir, y recargando), «La cámara está ocupada por otro programa», «La cámara tardó demasiado en abrir», «Esta compu no tiene una cámara conectada», o «La cámara no reconoció a nadie que pueda autorizar» y la pastilla «Mirar a la cámara» la prueba de nuevo. En las compus donde corre el fichador por cámara, el POS le pide solo al fichador que suelte la cámara un momento; puede tardar uno o dos segundos más. Si en cambio sale el cartel «Chrome no deja que el sistema le pida la cámara al fichador» (o la pastilla «Chrome te va a preguntar…»), lo que falta es un permiso de Chrome en esa compu: tocá «Permitir» en el cartelito de Chrome, o en la ventana del POS los tres puntitos → Información de la app → «Aplicaciones en el dispositivo» → «Permitir». Se hace una sola vez por compu (19-nov).', '3) Usuario y clave: en la misma ventana, abajo, quien autoriza escribe su usuario y su clave.', 'La cara se graba una vez en el Hub (engranaje → Mi cuenta → «Caras del equipo»). Si la computadora no tiene cámara o nadie con rango registró su cara, la ventana arranca directo en el camino 2.', 'La comparación de la cara se hace en el servidor: las huellas no se bajan a la computadora del local.'] },
    { icon: '🧊', titulo: 'Precio congelado: cuántos días se respeta el precio en presupuestos y señas', desc: 'Al armar un presupuesto o una seña, abajo, junto a la observación, aparece «Respetar el precio … días»: ahí se pone cuántos días corridos se le mantiene el precio al cliente. La casilla es celeste, viene vacía y es obligatoria: no hay ningún número propuesto, hay que escribirlo cada vez, tanto en el presupuesto como en la seña. Si se toca Emitir sin completarla, el POS avisa y no emite. Con 0 se emite sin congelar el precio. Ese plazo sale escrito en el comprobante que se lleva el cliente (comandera, hoja A4 y PDF), con la fecha hasta la que vale: «Los precios de este presupuesto se mantienen por 14 días corridos, hasta el 28/11» o, en la seña, «Los precios de lo señado se respetan por 30 días corridos, hasta el …; después se toman los precios vigentes». La plata de la seña no vence nunca: lo que vence es el precio congelado. Cómo se respeta después: 1) Presupuesto: en la pestaña Comprobantes, el botón «Facturar este presupuesto» lo carga en el ticket. Si está dentro del plazo, entra con los precios del presupuesto aunque hoy el artículo valga más, y avisa hasta cuándo valen. Si el plazo ya venció, carga los precios de hoy y avisa cuántos artículos cambiaron. La factura queda vinculada a ese presupuesto. 2) Seña: al cargar el cliente, el POS ofrece su seña; si está dentro del plazo, los artículos señados entran al precio congelado; si venció, entran al precio de hoy y avisa. En los dos casos, si igual corresponde respetar el precio viejo, se corrige el precio a mano en el ticket. Los presupuestos y señas anteriores a este cambio siguen como estaban: presupuesto 14 días, seña sin vencimiento de precio.' },
    { icon: '🎁', titulo: 'Pedirle a Clodi que arme una gift card', desc: 'Clodi puede dejar armada una gift card en el ticket. Se le dice, por ejemplo, «armame una gift card de 50.000 para María, de parte de Juan» y deja cargada la gift card en la pestaña Vender con el importe y los datos que se le dijeron (para quién, de parte de quién, dedicatoria, mail o WhatsApp de quien la recibe). Clodi no emite ni cobra: falta revisar, poner la forma de pago y tocar Emitir. El cliente también se lo podés pasar: si le decís el DNI o el CUIT («…para el DNI 20123456»), Clodi lo busca y lo deja cargado en el ticket, tanto en la gift card como en una factura o un presupuesto. Si ese documento no está en la base, con DNI queda cargado como cliente nuevo y falta escribirle el nombre; con CUIT se abre la ficha para completarla. Por nombre no lo busca: tiene que ser el número de documento. Si había un ticket empezado, pregunta antes de vaciarlo.' },
    { icon: '💬', titulo: 'Mandar el comprobante por mail o por WhatsApp', desc: 'Cuando se carga el cliente en el ticket, abajo aparece la casilla para mandarle el comprobante. Por defecto es el mail (casilla celeste, con el sobre): se escribe el mail, queda guardado en la ficha y la factura le llega sola por mail unos minutos después de emitir, como siempre. Dentro de la misma casilla, a la derecha, hay un botón redondo con el logo de WhatsApp: al tocarlo la casilla pasa a verde y pide el WhatsApp del cliente (código de área y número, por ejemplo 11 1234 5678); el número se guarda en el celular de la ficha, así la próxima vez ya viene cargado. Para volver al mail se toca el mismo botón, que ahora muestra el sobre. Al emitir, el comprobante sale por el canal que esté a la vista en la casilla: con mail, sale solo por mail; con WhatsApp, NO se manda el mail y, apenas está listo el PDF (unos segundos), se abre el chat de WhatsApp de ese número con el mensaje y el link al PDF ya escritos: falta tocar Enviar en WhatsApp. El sistema no puede enviarlo solo porque no usamos la API de WhatsApp; el chat se abre donde diga Ajustes → WhatsApp (en los locales, la ventana de WhatsApp del kiosco). Si el PDF tarda, queda el aviso en la ventana del comprobante. Además, cualquier comprobante abierto desde la pestaña Comprobantes tiene un botón verde de WhatsApp arriba: pregunta el número (propone el de la ficha) y abre el chat con el link, para mandarlo o reenviarlo cuando haga falta. Cada ticket nuevo arranca siempre en mail. En los remitos de traslado no aplica.' },
    { icon: '🧾', titulo: 'Modificar una factura electrónica (nota de crédito + factura nueva)', desc: 'Una factura con CAE no se puede anular ni tocar, pero sí reemplazar. En la pestaña Comprobantes, la factura tiene el lápiz «Modificar». Al tocarlo, avisa lo que va a hacer y carga la factura en el ticket con los mismos artículos, cliente, descuento y observación; en los totales aparece el renglón «Modificando Factura B 0003-… · ya cobrado», que descuenta lo que el cliente ya pagó. Se cambia lo que haga falta y se toca Emitir. Recién en ese momento el sistema hace las dos cosas juntas: 1) una nota de crédito por el total de la factura vieja, y 2) la factura nueva. Si algo falla no queda nada hecho, y si se cierra o se vacía el ticket sin emitir (o se toca la cruz del renglón «Modificando») no pasa nada: la factura queda como estaba. La plata: lo ya cobrado en la factura vieja pasa a la nueva tal cual, sin devolverlo ni volver a cobrarlo (tampoco se toca Mercado Pago). Solo se cobra la diferencia si el total subió, con la forma de pago que se elija. Si el total bajó, el POS muestra «se le devuelve al cliente en efectivo» y el importe; eso solo se puede si la factura vieja tenía efectivo suficiente. Si se había pagado todo con tarjeta, QR o transferencia y el total baja, no se modifica: se hace una nota de crédito por la diferencia, que es la que devuelve por Mercado Pago. El stock se acomoda solo: vuelve lo de la factura vieja y sale lo de la nueva. Quién puede: pide la misma autorización que una nota de crédito. La cajera, solo facturas del mismo día; de días anteriores, la encargada; de un mes anterior, solo un admin, porque cambia el IVA que ya presentó el contador. No se pueden modificar así: facturas que ya tienen una nota de crédito, señas o facturas que usaron una seña, gift cards, facturas pagadas con vale o gift card, y facturas hechas sobre un remito; en esos casos la nota de crédito se hace a mano. En Comprobantes, la factura nueva dice «reemplaza a #…» y la nota de crédito «devuelve #…». Al cliente le llegan por mail la nota de crédito y la factura nueva.' },
    { icon: '✏️', titulo: 'Modificar o anular un comprobante: qué se puede y qué no', desc: 'Lo electrónico que ya tomó ARCA (factura o nota de crédito con CAE, o esperando el CAE) NO se puede anular, nadie, con ningún usuario: tiene que coincidir siempre con ARCA. Para corregir una factura electrónica está el lápiz «Modificar» de la pestaña Comprobantes, que no la anula: hace la nota de crédito y la factura nueva (ver «Modificar una factura electrónica»). Las notas de crédito no tienen lápiz ni tacho. Lo que sí se puede modificar es lo que no va a ARCA, con el botón del lápiz que está junto a los otros botones del renglón: 1) Presupuesto (el del tilde «Presupuesto»): lo modifica cualquiera, también con el usuario genérico del local, sin autorización. 2) Comprobante X rojo (manual, sin el tilde): solo con autorización de la encargada (el mismo permiso que anular, que se maneja en el Hub → Permisos). Cómo funciona el lápiz: avisa lo que va a hacer, anula el original (en el X rojo la mercadería vuelve al stock) y lo deja cargado en el ticket con los mismos artículos, cliente, descuento y observación; se cambia lo que haga falta y se emite de nuevo, con un número nuevo. El original queda en la lista como Anulado con el motivo «Modificación». En el X rojo hay que cargar otra vez la forma de pago. No tienen lápiz las señas, las gift cards ni los comprobantes hechos sobre un remito. Quién puede según el día: la cajera puede anular o modificar (o autorizarlo cuando se lo pide el usuario genérico) solo lo emitido en el mismo día. Si el comprobante es de un día anterior, solo la encargada (o un admin): si lo intenta o lo autoriza una cajera, el sistema avisa «Este comprobante es de un día anterior: solo lo puede anular (o modificar) la encargada» y no hace nada. Vale para anular cualquier comprobante sin CAE (X rojo, remito, presupuesto) y para modificar el X rojo. Modificar un presupuesto sigue libre para cualquiera, sea del día que sea.' },
    { icon: '🔢', titulo: 'Cantidad de artículos del ticket', desc: 'Para controlar que lo que se separó en el mostrador coincide con lo que se cargó. En el ticket, arriba del Subtotal, la fila «Artículos» dice, en negrita, cuántas unidades hay en total (suma las cantidades de todos los renglones); si hay artículos que el cliente trae para cambiar (cantidad negativa) los cuenta aparte, como «de cambio». Al tocar Emitir (factura, presupuesto, nota de crédito o remito), antes que nada aparece un cartel celeste en forma de pastilla con el número en grande, por ejemplo «10 artículos por facturar», para contar que en el mostrador haya la misma cantidad. Con «Está bien, emitir» (o Enter) sigue; con «Volver» no emite nada y se puede corregir el ticket. No cuenta las señas, las gift cards ni los conceptos sueltos: en esos comprobantes el cartel no aparece.' },
    { icon: '🏬', titulo: 'Todos los locales juntos (solo admin)', desc: 'El admin tiene en el selector de local de arriba la opción «Todos los locales»: muestra todo junto, de todos los locales, solo para mirar (no tiene punto de venta, así que no se emite ni se arma nada). Se ven Comprobantes (con el local de cada uno y el total de cada local), Pedidos (los pedidos hechos de todos los locales), Remitos (pre-remitos, en tránsito, aceptados y movimientos de todos), Vales, Promociones, Online y Ajustes. Vender, Etiquetas y Caja se esconden. En las listas se pueden abrir los comprobantes, los PDF y los pagos, pero no crear, aceptar, anular ni modificar. Para operar se elige un local.',
      pasos: ['Arriba, en el selector de local, elegí «Todos los locales».', 'Se filtran igual que siempre: fechas, tipo, buscador y la pastilla «Pagos sin verificar» (de todos los locales).', 'En Pedidos se ve «Pedidos hechos» con el local que pidió adelante (Unicenter → Familia García…); en Remitos, el trayecto de cada traslado y el local de cada pre-remito y movimiento.', 'En Ajustes, lo que es de cada caja (Point, QR, quién tiene la cara registrada) pide elegir un local.', 'Para volver a facturar u operar, elegí el local en el mismo selector.'] },
    { icon: '✅', titulo: 'Pagos sin verificar: verificarlos después', desc: 'Cuando un cliente paga después (por ejemplo «hacé la factura que mañana te transfiero»), la factura se emite con la transferencia, el Point o el QR no integrado, o el link «sin verificar» (lo autoriza la cajera o la encargada). Esas facturas llevan en Comprobantes el cartel amarillo «Pago sin verificar», y la pastilla «Pagos sin verificar» (con contador) las muestra todas juntas, de cualquier fecha.',
      pasos: ['Cuando llega el comprobante del cliente, tocá el cartel (o el botón de pagos de la factura, o el de la ventana del comprobante) y después «Verificar».', 'El POS busca en Mercado Pago un cobro de ese importe desde el día de la factura: tocá el que coincide con el comprobante del cliente (fecha, hora, código). Queda conciliado con esa factura y no se puede usar en otra.', 'Si entró a una cuenta que no es Mercado Pago, «A mano»: se escribe el número de operación y queda anotado quién lo verificó (lo autoriza la cajera o la encargada).', 'El efectivo y los dólares no se «verifican»: si se cargaron mal, se corrigen (ver «Corregir la forma de pago»).'] },
    { icon: '🔁', titulo: 'Corregir la forma de pago de una factura emitida (solo la encargada)', desc: 'Si se cargó mal cómo pagó el cliente (efectivo en vez de transferencia, o al revés), se corrige sin rehacer la factura: la forma de pago no viaja a ARCA, así que mientras el importe sea el mismo la factura no cambia ante ARCA. Lo que sí cambia es la caja de ese día y lo que dice «Pagos» en el PDF (se rearma solo; el mail que ya salió no se vuelve a mandar).',
      pasos: ['En el pago de la factura (botón de pagos), «Corregir»: se elige cómo se pagó (efectivo, dólares con la cotización, transferencia, Point o QR no integrado, QR o cuenta corriente), la referencia si hay y por qué se corrige (obligatorio).', 'Lo hace la encargada; si lo pide otra persona, sale el pedido de autorización y solo la encargada (o un admin) puede autorizarlo. Se maneja en el Hub → Permisos («Corregir la forma de pago de un comprobante emitido»).', 'No se puede corregir un pago ya verificado en Mercado Pago, uno del Point integrado, un vale o una gift card.', 'Si se pasa a transferencia, Point o QR, queda «sin verificar» hasta que llegue el comprobante.', 'Queda anotado qué decía antes, qué dice ahora, quién lo hizo, quién lo autorizó y por qué. Si ese día ya está en la planilla de ventas, el POS avisa para que administración la corrija.', 'Cambiar el importe, el cliente o los artículos sí necesita nota de crédito y factura nueva (eso está en ARCA).'] },
    { icon: '🔍', titulo: 'Vista previa del comprobante: acercar para leer', desc: 'En la ventana de la vista previa (o al abrir un comprobante) la hoja A4 entra entera; para leerla se acerca con la rueda del mouse (acerca justo donde está el mouse) o con el + de arriba, al lado de Hoja A4 / Comandera. El − o la rueda para el otro lado alejan, y «Entera» la vuelve a meter toda en la ventana. Para moverse por la hoja acercada se la arrastra con el mouse (o con las barras). Si el comprobante tiene varias hojas (por ejemplo el remito, con original y duplicado), se ven todas una abajo de la otra. Sirve igual para la comandera.' },
    { icon: '📅', titulo: 'Seña y presupuesto: hasta qué fecha se respeta el precio', desc: 'La cajera pone cuántos días se le respeta el precio (siempre días corridos, cuentan sábados, domingos y feriados) y al lado ya ve hasta qué fecha queda. En el comprobante no dice «por tantos días»: dice hasta qué fecha («Los precios de este presupuesto se mantienen hasta el 03/12/2026»; en la seña, «Los precios de lo señado se respetan hasta el 03/12/2026»). Con 0 días no se congela el precio.' },
    { icon: '🪙', titulo: 'Quién emite y quién atendió: las monedas con las caras', desc: 'En la ventana de «¿Quién emite y quién atendió?» cada persona aparece como una moneda redonda con su cara (la foto de su legajo en RRHH) y abajo, en chico, su nombre. Si alguien no tiene foto cargada, la moneda muestra sus iniciales.',
      pasos: ['Se toca la moneda de quien emite (arriba, en celeste) y la de quien atendió (abajo, en verde): la elegida queda con un aro de color.', 'En el comprobante (factura, presupuesto, nota de crédito, comandera y PDF) sale quién atendió en sala y quién en caja: «Te atendió Andrea en sala y Romina en caja». Si es la misma persona: «Te atendió Romina, en sala y en caja». Sin sala (Oficina, nota de crédito o «Por su cuenta»): «Te atendió Romina en caja».', 'En Oficina no se pregunta quién atendió (ni en facturas, ni en presupuestos, ni en notas de crédito): la ventana es solo «¿Quién emite?». En los locales se pregunta en las ventas; en la nota de crédito y el remito, nunca.', 'Si la cámara reconoce a quien emite, su moneda ya aparece marcada y solo falta tocar quién atendió. Esa moneda no se cambia a mano: si la cámara tomó a otra persona (por ejemplo, dos vendedoras mirando la cámara a la vez), la que está facturando toca su moneda y mira de frente a la cámara; si la cámara la reconoce, se cambia; si no, queda la que estaba.', 'El reconocimiento se prepara solo al abrir el POS, así la cámara anda bien desde la primera factura.', 'Si al cliente no lo atendió ninguna vendedora, se toca la moneda gris «Por su cuenta» (con una bolsita): queda anotado así para las estadísticas, y en el ticket del cliente sigue diciendo «Te atendió» con el nombre de quien emitió.', 'Para que aparezca la cara, la foto se carga en el legajo de la persona en RRHH.'] },
    { icon: '📷', titulo: 'Quién emite · reconocimiento por cámara', desc: 'En el local queda abierto el usuario genérico, así que el POS necesita saber qué persona emite cada comprobante. Al tocar Emitir (factura, nota de crédito, remito, presupuesto) la cámara lee en segundo plano, sin mostrarse: aparece «Un momento…», reconoce a quien está en la caja, avisa «Emite …» y sigue solo. La ventana «¿Quién emite?» se abre solo si no reconoce a nadie en unos 7 segundos (para elegir el nombre a mano) o si falta marcar quién atendió. El nombre queda en el comprobante como quien emitió. En las ventas (factura, presupuesto, comprobante X, gift card) la misma ventana trae las dos preguntas, «¿Quién emite y quién atendió?», porque muchas veces quien cobra no es quien atendió. Arriba, «Emite (en la caja)»: lo resuelve la cámara sola cuando el reconocimiento está prendido; si está apagado o no reconoce, se toca el nombre. Abajo, «Atendió al cliente»: siempre se toca el nombre de la vendedora (puede ser la misma persona). Cada pregunta está en su panel de color (celeste la de quién emite, verde la de quién atendió) y los nombres se muestran solo por el apellido; si en el local hay dos personas con el mismo apellido, se agrega la inicial del nombre. El elegido queda pintado. Cuando están las dos, la ventana sigue sola, sin botón. Quedan anotadas las dos personas por separado. Si quien entró lo hizo con su usuario personal, solo pregunta quién atendió. El ticket dice «Te atendió» con ese nombre y en la lista de comprobantes aparece «atendió …» cuando es otra persona. En notas de crédito y remitos no lo pregunta. Registro de quién hizo cada cosa: en el Hub → Permisos → Perfiles, cada función tiene la marca «📷 Registra quién: Sí / No» (una sola por función, vale para todos los perfiles). Si JP marcó una función del POS con «Registra quién», al usarla se pide quién la está haciendo (por la cara, o tocando tu nombre en la lista) y queda anotado en el Hub → Permisos → Registro, con la cuenta, el local, la hora y el detalle de la operación; con usuario personal se anota solo, sin preguntar. Al emitir no pregunta de nuevo: usa a quien ya se eligió en «¿Quién emite?». En el resto (anular un comprobante o un vale, mínimos, pedidos, marcar renglones en «Me piden», devolver la card física de una gift card, movimientos de stock, recibir o rechazar mercadería) aparece la ventana «¿Quién lo está haciendo?» después de la autorización, si la pide. Si se cancela esa ventana, la operación no se hace. No se guarda ninguna foto.',
      pasos: ['Registrar la cara: las caras ya no se graban en el POS, se graban en el Hub. Cada persona puede hacerlo en el Hub → engranaje → Mi cuenta → «Caras del equipo», y un admin también desde el Hub → Permisos → «Personas». Lo que se graba ahí es lo mismo que usa el POS para reconocer a quien emite y a quien autoriza: no hay que hacer nada más. En el POS, Ajustes → «Quién emite · reconocimiento por cámara» muestra quién tiene la cara grabada (con cuántas tomas y desde cuándo) y quién no, y tiene el botón «Probar la cámara», que abre la misma ventana que aparece al emitir y dice a quién reconoció, sin emitir nada. Ahí ya no hay botones para grabar ni para borrar caras.', 'La cara aprende sola: cada vez que la cámara te reconoce, o elegís tu nombre justo después de que la cámara te leyó, el sistema guarda esa lectura como una toma más tuya (hasta 6, las más nuevas pisan a las viejas). Así, con los días, el POS te conoce con la luz y la cámara de tu caja y cada vez reconoce mejor. Solo guarda la lectura si se parece a tu cara grabada y no a la de una compañera: tocar el nombre equivocado no le enseña nada.', 'Si en esa computadora también corre el fichador por cámara (el de la mano para fichar), el POS le pide la cámara antes de leer y se la devuelve al terminar: si alguna vez dice «la cámara está en uso», esperá unos segundos y volvé a tocar Emitir.', 'Mientras el reconocimiento por cara esté apagado (se prende y se apaga desde el Hub), la ventana «¿Quién emite?» no abre la cámara: dice «El reconocimiento por cara está apagado por ahora: elegí tu nombre» y se elige el nombre a mano. Las autorizaciones, mientras tanto, van por el celular o con usuario y clave. En Ajustes → «Quién emite» también avisa que está apagado.', 'Al emitir: mirar hacia la cámara aunque no se vea la imagen; cuando aparece «Emite …» con el nombre, sigue solo. Es obligatorio: sin saber quién emite no sale el comprobante.', 'Si no reconoce, la computadora no tiene cámara o todavía nadie registró su cara: en la misma ventana se elige el nombre a mano entre las empleadas del local. Los admin aparecen siempre en esa lista, en cualquier local, porque pueden emitir desde cualquiera. Si la cámara no abre, la ventana dice por qué (sin permiso del navegador, no hay cámara, o la está usando otro programa).', 'Si quien entró al POS lo hizo con su usuario personal de empleada (no el genérico), no abre la cámara: ya sabe quién es y avisa «Emite …» con su nombre. Con el usuario genérico del local o con un usuario admin siempre pasa por la cámara.', 'No se guarda ninguna foto ni video: solo una huella numérica de la cara, que se puede borrar o volver a grabar desde el Hub.', 'La primera vez que se usa en cada computadora tarda unos segundos más porque baja el reconocimiento; el navegador pide permiso para usar la cámara y hay que aceptarlo.'] },
    { icon: '💬', titulo: 'Botones de WhatsApp', desc: 'Los botones de WhatsApp del POS (mandar un vale o una gift card, el pedido al proveedor) se abren donde esa computadora tiene la sesión de WhatsApp del local.',
      pasos: ['En las PC de los locales el chat se abre en la ventana de WhatsApp del kiosco (la misma que usa el módulo Clientes), con el mensaje ya escrito: solo queda apretar enviar.', 'La primera vez el navegador pregunta si permite abrir el programa: tildá «Permitir siempre» y aceptá.', 'Si un botón de WhatsApp abre una página que pregunta «app o WhatsApp Web» o pide escanear un QR, esa computadora no está configurada: avisale a JP.', 'Se configura una sola vez por computadora (solo admin): Ajustes → «WhatsApp en esta computadora» → «Ventana de WhatsApp del kiosco». También sirve abrir el POS una vez con ?wa=kiosco al final de la dirección. En los celulares no se toca nada: abre la app de WhatsApp como siempre.'] },
    { icon: '🧪', titulo: 'Ambiente de prueba', desc: 'Mientras arriba de todo aparece la franja roja «AMBIENTE DE PRUEBA», el POS está en modo prueba para todos los locales: se puede practicar todo (facturas, notas de crédito, presupuestos, remitos, señas, gift cards, vales, pedidos, etiquetas) sin que nada sea real.',
      pasos: ['Las facturas y notas de crédito de prueba NO van a ARCA: no tienen CAE ni valor fiscal. Salen con numeración propia (punto de venta 9999) y con la leyenda «PRUEBA · SIN VALOR FISCAL» en el ticket, en la hoja A4 y en el PDF. En Comprobantes figuran con la etiqueta roja «Prueba».', 'El stock no se mueve: una venta de prueba no descuenta mercadería (el movimiento queda anotado en el historial del artículo, marcado como prueba, solo para ver cómo funciona).', 'La caja de prueba es aparte: en Caja se ve solo lo cobrado en prueba.', 'Mails: ningún mail de prueba le llega al cliente ni al proveedor. Todos van a la casilla de prueba (la de JP), con «[PRUEBA]» en el asunto.', 'Gift cards, vales de cambio y señas de prueba se generan y se usan solo dentro de la prueba: un vale de prueba no sirve en una venta real y uno real no se puede gastar en prueba.', 'Pedidos: el pedido a Familia García NO sale al proveedor; el mail va a la casilla de prueba y el botón de WhatsApp abre el número de prueba. El pedido a Oficina y los remitos de traslado funcionan entre los locales, pero el módulo Stock no los ve.', 'OJO con el Point: Mercado Pago cobra de verdad aunque el comprobante sea de prueba. Usalo solo si JP pidió probarlo (cobro y devolución).', 'Las autorizaciones al celular llegan con «PRUEBA» en el título.', 'Solo el admin, desde Ajustes → Ambiente de prueba, pasa el POS a REAL (hay que escribir REAL para confirmar), vuelve a prueba, cambia el mail y el WhatsApp de prueba, y borra todo lo de prueba cuando ya no hace falta. Al pasar a real lo de prueba deja de verse.'] },
    { icon: '🔐', titulo: 'Entrar y elegir el local', desc: 'Las dos cuentas de la oficina (administracion@claudiaadorno.com y claudiaadorno@claudiaadorno.com) entran directo en Oficina y ahí usan todo el POS: vender, comprobantes, remitos, caja, pedidos que le hacen los locales, etiquetas y vales. En el selector de local también les aparecen Alcorta y Unicenter con la marca «solo ver»: ahí pueden mirar los comprobantes, la caja y los pedidos de ese local, pero no pueden vender, emitir ni cambiar nada en nombre del local. Para operar tienen que volver a Oficina. También ven Ajustes, pero solo para mirar: aparece el cartel «Ajustes · solo para mirar» y no se puede tocar ni guardar nada; los cambios los hace un admin. El registro de quién hizo y quién autorizó y la planilla siguen siendo solo de los admin. Entrás con tu usuario de Colaboradores. Arriba, al lado del título, se elige desde qué local se factura: las vendedoras y encargadas pueden usar su propio local u Oficina (para lo que se factura desde allá), nunca el otro local; el admin elige cualquiera.',
      pasos: ['Lo que emitís sale con el punto de venta y la numeración del local elegido, y aparece en los Comprobantes y la Caja de ese local.', 'Si dice que no tenés acceso, tu legajo no tiene local asignado: avisale a JP.', 'Código del celular (doble factor): si sos admin o directora y lo activaste en el Hub (panel de sesión, "Código del celular al entrar"), en cada computadora te pide, después de la clave, el código de 6 números de la app de autenticación del celular (Google o Microsoft Authenticator), y después una vez cada 30 días. En el celular registrado con "Entrar con la cara en este equipo" no hace falta ni clave ni código: te pide la cara (o la huella) al abrir. Si cambiás o perdés el celular, avisale a JP para darlo de baja.', 'En el celular o la tablet se instala como app: Safari "Compartir → Agregar a pantalla de inicio"; Chrome "Instalar".'] },
    { icon: '🛒', titulo: 'Vender', desc: 'Los renglones del ticket van en colores alternos (blanco y celeste clarito) para leerlos más fácil. En la computadora cada renglón muestra la foto grande, el código, la descripción y debajo la descripción adicional, con cantidad, precio, descuento e importe en letra más grande. En el celular o en una ventana angosta el renglón va compacto: solo código y descripción, sin la descripción adicional. A la izquierda buscás los productos; a la derecha se arma el ticket. Cantidad primero: escribís 12 y + (o 12+) y Enter, queda el chip 12 ×, y el próximo producto que escanees, escribas o toques entra con 12 unidades; también todo junto, 12 SMINI. Sirve en factura, nota de crédito, presupuesto, remito y artículos señados. Cambios: si el cliente trae un artículo, se escribe la cantidad en negativo en la factura (por ejemplo -1): se descuenta del total y ese artículo entra al stock; el renglón queda violeta con el chip cambio · entra. En la nota de crédito es al revés: el negativo sale del stock. El total nunca puede quedar negativo. La vista previa de la hoja A4 se escala sola para que entre entera en la pantalla. Doble clic sobre un producto de la lista o sobre la ficha (o el link Ficha completa) abre en una subventana la ficha completa del módulo Productos, con todo lo que tiene cargado; se puede abrir en pestaña aparte. Doble clic sobre la ficha del producto, o sobre un renglón del ticket, abre en una subventana la ficha completa del módulo Productos (ahí están el historial de movimientos de stock y el resto de los datos). La ficha de la izquierda no tiene enlaces: muestra la foto con el stock de cada local debajo, y a la derecha el código, la descripción y la descripción adicional siempre completos (si son largos la letra se achica para que entren), el material y el nombre del proveedor (sin título, separados por un punto), y el precio con el botón + abajo. Para sacar el cliente del ticket está la cruz roja gruesa, a la derecha de sus datos; la misma cruz roja saca un renglón del ticket. El CUIT o CUIL del cliente se puede escribir o pegar con guiones, puntos o espacios (30-70967311-0): el sistema se queda con los números, tanto en el buscador de clientes como en la ficha de alta. Hasta el cierre del año el stock que se muestra viene del Dragonfish y el libro ya anota cada movimiento; después manda el libro: la factura o el comprobante X bajan el stock, la nota de crédito lo sube, la anulación lo deshace, la seña no lo toca (es una reserva) y la gift card no es un artículo. Al cargar un cliente que tiene remitos sin facturar, el POS avisa y ofrece Facturar este remito: entran los artículos marcados entregado y esa factura no vuelve a descontar stock. En el banner de arriba, A− y A+ agrandan o achican la letra, los números, las casillas y las fotos de todas las pestañas (Vender, Comprobantes, Caja, Vales, Configuración), de 90 a 150 %; el banner no cambia. En Vender se arrastra la barrita gris del medio para repartir el ancho entre productos y ticket. La flechita ↺ del banner vuelve a lo normal (letra 100 % y reparto de siempre). Queda guardado en esa computadora o tablet (cada una tiene el suyo). En el celular no hay A−/A+ y las ventanas van una debajo de la otra. Es la pantalla del mostrador.',
      pasos: ['Escribí parte del código o de la descripción: arriba a la izquierda aparece la ficha del primer resultado (foto grande, descripción, material, proveedor, stock en cada local y precio), siempre del mismo tamaño para que no salte al pasar de un artículo a otro y abajo la lista. Pasando el mouse por otro de la lista la ficha cambia; tocándolo, o con el botón Agregar de la ficha, entra al ticket. En el ticket cada renglón muestra una miniatura de la foto. Al agregar un artículo o subir la cantidad suena un bip que sube; al sacarlo o bajar la cantidad, uno que baja (hay que tener el volumen de la compu prendido). También se le puede preguntar a Clodi, escrito o por voz: «¿hay bandeja roja grande?», «buscame la SMINI», «la B roja gde» o «¿en qué local queda la ACRISD?» (19-nov). Clodi hace la búsqueda en Vender, deja la ficha a la vista y te dice el stock de cada local y el precio (hasta tres artículos; si hay más, lo avisa). No carga nada en el ticket. Entiende lo dictado: abreviaturas (GDE, CH, BCO), rojo o roja, plurales, una letra suelta como inicial (la «B» de bandeja) y códigos dichos a medias; si no encuentra las palabras exactas, muestra lo más parecido y lo avisa. Si hay un ticket armado (artículos, gift card o seña) y algo te saca del POS —cerrar la ventana, recargar la página, ir al Hub, tocar «Ir a …» en Clodi o pedirle «llevame a …»—, Chrome pregunta «¿Salir del sitio?» antes de irse: «Cancelar» te deja en el POS con el ticket como estaba; «Salir» lo pierde (19-nov). Con el botón Salir del POS pregunta el POS mismo: «Hay un ticket armado sin emitir: si salís, se pierde. ¿Salir igual?». Abrir WhatsApp, un mail o un teléfono no pregunta. Y Clodi, con un ticket armado, no te lleva sola a otro módulo: contesta «No te llevo todavía porque hay un ticket armado sin emitir. Cuando termines, tocá el botón…», y su botón «Ir a …» pregunta antes de salir.', 'Con el lector de etiquetas: escaneá el QR con el cursor en el buscador y el artículo entra solo (el QR trae el SKU).', 'Los artículos y los precios se ponen al día solos, sin recargar la página (25-nov): cada 3 minutos, al volver a la pestaña del POS y cuando se busca o se escanea algo que no está. Un artículo recién dado de alta se puede escanear enseguida: el POS lo busca en el sistema y lo suma al ticket. Si cambia el precio de un artículo que ya está en el ticket, el renglón toma el precio nuevo y aparece un aviso con el precio de antes y el de ahora; si ese precio se había cambiado a mano, queda el que se puso. En la nota de crédito, al modificar un comprobante y en lo que viene de un presupuesto, un remito o una seña, el precio no cambia.', 'En cada renglón podés cambiar la cantidad (+ / −), el precio y el descuento (casilla Dto): un número solo son pesos que se descuentan al precio unitario (1000 = $1.000 por unidad); con % al final es porcentaje (10%). Abajo hay un descuento general con la misma regla que el Dto del renglón: un número solo son pesos (5000 = $5.000), con % al final es porcentaje (10%). Con el "+" del renglón se agrega otro descuento; se aplican en cascada, cada uno sobre lo que queda. Con descuento en pesos el total cierra exacto.', 'Arriba elegís qué sale con las pastillas Factura, Nota de crédito y Presupuesto. Al tocar Presupuesto, abajo junto a la observación aparece un tilde "Presupuesto": sin tildar es un comprobante manual (interno, no va a ARCA), tildado es un presupuesto de verdad. La letra no se elige: Factura sale B (consumidor final, monotributista, IVA exento, no responsable o no alcanzado; todos menos consumidor final llevan CUIT), Factura A (responsable inscripto, pide CUIT), Factura manual (comprobante interno X que no va a ARCA), las notas de crédito B y A (devoluciones) y Presupuesto (no es venta: no va a ARCA ni a la caja, y después se factura desde Comprobantes con el botón de cobrar).', 'Al cargar un cliente con CUIT la pastilla pasa sola a "Factura A" (si el cliente no tiene condición de IVA cargada, con CUIT se lo toma como responsable inscripto; si es monotributista o exento, corregilo en la ficha o dejá que el padrón de ARCA lo complete, y vuelve a B) y abajo del subtotal aparecen el neto gravado y el IVA 21%, como en el comprobante; si lo sacás, vuelve a B. La nota de crédito toma la letra de la factura que devuelve. El documento cambia de fondo según el tipo: naranja claro cuando es nota de crédito, rojo clarito cuando es manual y celeste cuando es presupuesto, para notarlo de un vistazo. Mercado Pago Point integrado: primero, en Ajustes, "Mi Point en esta caja": cada computadora o tablet elige su terminal y queda guardado ahí. En el ticket, con forma de pago Mercado Pago Point (Integrado) aparece el botón "Cobrar $ en el Point": manda el importe a la terminal, se abre la ventana "Esperando el pago" y el cliente elige cuotas y pasa la tarjeta en el Point (mínimo $ 15; vence a los 3 minutos). Si la terminal no lo muestra, tocá el botón verde del Point. Cuando Mercado Pago aprueba, el renglón queda "pagado" en verde con el número de operación y recién ahí se puede emitir la factura. Rechazado, cancelado o vencido: no se emite nada, se reintenta o se cambia el medio. "Cancelar el cobro" lo cancela desde el POS; también se puede cancelar en la terminal. Si el Point tiene un cobro sin terminar, hay que finalizarlo o cancelarlo en la terminal antes de mandar otro. Devoluciones: una nota de crédito sobre una venta cobrada con Point integrado, con forma de devolución Mercado Pago Point, devuelve la plata a la misma tarjeta por Mercado Pago al emitir (hasta 90 días); si Mercado Pago no lo permite, el POS avisa y se hace desde la terminal. "No integrado" sigue siendo cobrar a mano en el Point y anotar el cupón. Gift card digital: escribí "gift" en el buscador y tocá la pastilla. Entra un renglón "Gift card" con el importe libre (sin descuento) y abajo el cuadro: para quién, de parte de quién, mail o WhatsApp de quien la recibe, la dedicatoria y el tilde "Mostrar el importe en la tarjeta" (sin tildar, el regalo no dice el precio; quien la recibe ve su saldo con el link). En todas las casillas de plata (precio, importe de la gift card, pagos, dólares) el separador de miles aparece solo mientras se escribe (23000 se ve 23.000); los centavos van con coma. Para venderla: escribí «gift» en el buscador de productos; aparece la tarjeta negra con una casilla de importe. Escribí el importe (se ve en la tarjeta), Enter o «Agregar», y pasa al ticket con ese importe ya puesto; después se completa para quién es y a dónde se manda. Se cobra con cualquier medio y sale con FACTURA legal (B, o A si el cliente es responsable inscripto): la gift card se factura al venderla, con CAE, y entra en la caja del día como venta (decisión de JP, 9-nov-2026). La gift card va siempre con la pastilla Factura: si se cambia a Presupuesto o a Nota de crédito, la gift card se saca del ticket. Cuando la usan, esa plata ya está facturada: en la factura de la compra la gift card se descuenta del total (renglón «Gift card ya facturada», como la seña), se factura solo la mercadería y se paga la diferencia con cualquier medio; si la compra es menor que la gift card, la factura sale en cero y queda saldo para otra vez. El uso de la gift card no entra en la caja (la plata entró el día que se vendió). Las gift cards viejas que salieron como comprobante X (antes del 9-nov) siguen usándose como forma de pago común. El vale de cambio no cambia: nace de una nota de crédito, así que la compra nueva se factura entera y el vale es un medio de pago. En el ticket, el renglón de la gift card se reconoce por la tarjetita negra en chiquito. El vale de cambio se manda por mail y por WhatsApp a la vez: al devolver con vale hay dos casillas, mail y WhatsApp, que vienen cargadas con los datos del cliente. Al emitir aparece el código (GC-XXXX-XXXX-XXXX) con su QR: el mail lo manda el servicio solo, con la tarjeta y la dedicatoria, y en la misma ventana está la casilla del WhatsApp con el botón «Enviar por WhatsApp», que abre el chat con el mensaje y el link listos (si no se había cargado el número, se escribe ahí mismo; sirve igual para la gift card); sin contacto, se copia el link y se pasa a mano. La tarjeta se ve en una página web: frente con la dedicatoria, se toca y gira al dorso con el código y el QR, y abajo el saldo. No vence y se puede usar en varias compras hasta agotar el saldo. Vale de cambio: en una nota de crédito, en "Cómo se le devuelve la plata" elegí "Vale / Gift card": no se mueve plata, al emitir nace un vale (VC-XXXX-XXXX-XXXX) por ese importe a nombre del cliente de la factura, sin vencimiento, y se manda al mail o WhatsApp que figura en ese renglón (con la nota de crédito adjunta si va por mail). Cobrar con un vale o una gift card: medio de pago "Vale / Gift card" y el código tipeado o escaneado con el lector (si se escanea el QR con el cursor en el buscador, el POS lo manda solo al renglón de pago). El POS consulta el código al instante: verde con el saldo si está vigente (sugiere usar el saldo o lo que falta, lo que sea menor; el resto queda en el mismo código), rojo si no existe, está anulado o ya se usó entero (dice cuándo y en qué factura). No se puede emitir con un vale sin verificar, ni usar el mismo código dos veces en un ticket, ni pagar una gift card con otro vale. Nunca se devuelve en efectivo el resto de un vale. El canje se hace en la base en el mismo paso que la factura, así dos cajas no pueden usar el mismo código a la vez. Pestaña Vales (menú de arriba): lista gift cards y vales con para quién, de qué comprobante nacen, importe, saldo y si el mail salió; se puede buscar por código, nombre o mail. El ojo muestra en qué compras se usó, el sobre lo reenvía (a otro mail o WhatsApp si hace falta), el documento abre la tarjeta y la cruz lo anula con motivo (encargada o admin; un vale usado entero no se anula). Anular el comprobante que vendió una gift card anula la gift card si todavía está intacta. Seña: escribí "seña" en el buscador y tocá la pastilla azul. Entra un renglón "Seña a cuenta" donde ponés la plata que deja el cliente, y abajo la subtabla "Artículos señados": buscá y tocá los productos que reserva (con su cantidad). Hace falta cliente con DNI o CUIT. Sale como factura por el importe de la seña; los artículos quedan reservados (se restan del stock que se ve) y no vence. Cuando el cliente vuelve y lo cargás, el POS avisa en un cartel en pastilla que tiene una seña (con el importe, la fecha, la factura y lo reservado; si tiene varias, una pastilla por cada una) y con "Usar esta seña" entran los artículos reservados al precio que tenían el día de la seña (si hubo aumento, lo señado no aumenta) y se descuenta lo ya pagado: la factura sale por el total menos la seña y paga el saldo. El total tiene que ser igual o mayor que la seña. Si no retira, la seña se cancela con una nota de crédito de su factura. Nota de crédito: elegís la pastilla y abajo aparece un cuadro naranja para buscar la factura que devuelve (número como 35-2, DNI o nombre del cliente). Al tocarla entran sus artículos al ticket: sacá o bajá la cantidad de lo que no vuelve. El cliente es el mismo de la factura y no se cambia. Abajo elegís cómo se le devuelve la plata.', 'El ticket arranca sin cliente: en el cuadro Cliente se carga el DNI o CUIT (tipeado o escaneando el DNI con el lector). Si existe lo trae; si no, abre la ficha para darlo de alta. Con consumidor final la factura B va a ARCA sin datos del cliente (él queda en nuestra base); si el cliente pide la factura con sus datos, tildá "a su nombre" (arriba del tope de ARCA va identificada sí o sí). Abajo del cliente hay una casilla aparte con su mail, que es por donde se manda la factura: es opcional; si se escribe ahí mismo, Enter o salir de la casilla lo guarda en la ficha. Alta rápida de cliente: si escribís un DNI que no existe, no se abre la ficha; queda el DNI en el ticket y abajo aparecen dos casillas, «Nombre y apellido» y «Mail». Escribís el nombre completo de corrido (Juan Pablo Simonelli) y el sistema lo separa solo en nombre y apellido (la última palabra es el apellido; si el apellido es compuesto, escribilo con coma: Pérez García, Ana); Enter lo da de alta y pasa al mail, que es opcional. Si el DNI se escanea, el nombre sale del DNI y el cliente queda dado de alta sin escribir nada. El lector funciona aunque la compu tenga el teclado en español (ahí escribe comillas en vez de arrobas). Para completar más datos (celular, dirección, cumpleaños) tocá el cliente y se abre la ficha. No se puede emitir con un cliente nuevo sin nombre: se carga o se saca con la X. Ver la sección Clientes.', 'Un renglón con borde ámbar es un artículo sin stock en este local: se vende igual, pero avisá. Cambiar de pastilla (Factura, Nota de crédito, Presupuesto) no borra los artículos cargados. Al lado de las pastillas hay tres botones: el tacho limpia todo el documento, el ojo muestra una vista previa (sin emitir, sin número ni CAE) con dos pestañas, Hoja A4 y Comandera (abre siempre primero en la Hoja A4, tanto en la vista previa como al abrir un comprobante ya emitido; la Hoja A4 es lo que le llega al cliente por mail; la comandera queda como segunda pestaña, por si la quieren mirar. El botón de la impresora de esa ventana imprime siempre por la comandera, se esté viendo la pestaña que se esté viendo: es para el cliente que quiere llevarse algo impreso. La única excepción son los comprobantes que no salen por comandera, que son los remitos, los comprobantes X y los presupuestos: esos se imprimen en hoja A4), y la impresora de al lado manda la comandera a imprimir; desde la pestaña Hoja A4 de la vista previa se imprime la A4.'] },
    { icon: '🪪', titulo: 'Escanear el DNI de un cliente que ya existe', desc: 'Si se escanea el DNI de un cliente que ya está cargado, el POS lo trae y completa en su ficha lo que le falte con los datos del DNI: la fecha de nacimiento (para el cumpleaños), el sexo y el nombre o el apellido si no estaban. Lo que ya estaba cargado no se toca.',
      pasos: ['Al completar avisa, por ejemplo: «Con el DNI completé la fecha de nacimiento y el sexo en la ficha de Ana».', 'Lo completado también va al Dragon, como cuando se da de alta un cliente.', 'Antes solo se completaba si el cliente ya tenía mail cargado: ahora siempre.'] },
    { icon: '👤', titulo: 'Clientes', desc: 'Mientras escribís en la casilla del cliente (nombre, DNI o CUIT, 3 letras o números) se abre un desplegable con las 5 coincidencias más cercanas, con documento y última compra: tocás una o Enter toma la primera. En el buscador de productos pasa lo mismo: muestra las 5 más cercanas y avisa cuántas más hay. Todas las ventas llevan cliente: así queda en nuestra base para mandarle la factura, saludarlo en el cumpleaños y saber qué compra. Se identifica por DNI o CUIT, nunca por un código.',
      pasos: ['En el cuadro Cliente del ticket escribí el DNI (7 u 8 dígitos) o el CUIT (11) y Enter, o pasá el DNI por el lector de códigos (lee el código de atrás del DNI, también el DNI viejo): trae apellido, nombre, fecha de nacimiento y sexo solos. Si el cursor estaba en el buscador de artículos, también lo detecta.', 'Si el cliente ya está en la base, aparece en el ticket. Si es un CUIT que no existe se abre la ficha (trae los datos de ARCA): con * es obligatorio (documento y apellido o razón social); mail, celular, dirección, fecha de nacimiento y condición de IVA se pueden completar otro día. El celular se guarda en formato WhatsApp.', 'Con CUIT el POS consulta solo el padrón de ARCA y trae razón social, condición de IVA y domicilio. Responsable inscripto → factura A; monotributista, exento, no responsable o no alcanzado → factura B con CUIT.', 'Tocando el cliente en el ticket (o el lápiz) se abre la ficha para corregirla. A la izquierda muestra desde cuándo es cliente, cuántas compras lleva y qué se llevó la última vez (con foto): sirve para charlar con el cliente, por ejemplo preguntarle cómo le resultó lo que compró. La cruz lo saca del ticket. La lupa busca por nombre si no tenés el documento.', 'Abajo del tope de ARCA la factura B sale a "Consumidor Final" sin datos aunque el cliente esté cargado: a ARCA no va nada y el cliente queda vinculado en nuestra base (en Comprobantes se ve con 👤). Desde el tope (hoy $10.000.000, el sistema lo relee en ARCA todos los meses) la factura va identificada sí o sí.', 'Si cobrás sin cliente, aparece el cartel celeste «No cargaste cliente» con dos botones: «Cargar cliente» (vuelve al ticket con el cursor en la casilla del cliente) o «Consumidor Final» (emite sin cliente). Queda registrado qué ventas salieron sin cliente.', 'Lo que se carga o corrige también se manda al Dragonfish hasta fin de diciembre, para que los dos sistemas tengan lo mismo.'] },
    { icon: '💳', titulo: 'Cobrar', desc: 'Gift card con card física (desde el 13 de noviembre): la gift card es digital por defecto (le llega a quien la recibe por mail o WhatsApp). Si el cliente quiere llevarse algo en la mano, al vender la gift card se tilda «Se lleva la card física» y se escanea o se escribe el código de 8 números que tiene impreso la card. Se cobran $ 5.000 más (el cargo se cambia en Ajustes → «Card física de la gift card»): en la factura sale la gift card en un renglón y la card física en otro. Ejemplo: gift card de $ 50.000 con card física, el cliente paga $ 55.000 y el saldo para comprar es $ 50.000. Si quien recibió el regalo después nos devuelve la card física, esos $ 5.000 se le suman al saldo: compra por $ 55.000. No se devuelve plata, se suma para comprar. Para usarla: en el pago se elige «Vale / Gift card» y se escribe o escanea el código de la gift card o el de la card física, los dos llevan al mismo saldo. Ahí aparece el botón «Devuelve la card física · suma $ 5.000»: se toca solo si entrega la card en ese momento; se puede devolver aunque el saldo ya esté en cero. La card devuelta queda libre para otra gift card. El POS no acepta una card que ya está entregada con otra gift card, ni un código que no sea de una card. Hay 12 cards que tienen un importe cargado en el Dragonfish (pueden estar vendidas con el sistema viejo): el POS no las deja usar hasta que un admin las revise. En el comprobante X (el rojo, Presupuesto sin tildar) la única forma de pago es efectivo, en pesos o en dólares; el renglón viene ya en Efectivo. Efectivo dólares: elegís ese medio, escribís los dólares y el sistema calcula los pesos con el tipo de cambio del día (promedio entre compra y venta del dólar billete del Banco Nación, se actualiza solo cada hora; se puede corregir en el renglón). El ticket y el A4 muestran US$ × tipo de cambio y el importe en pesos; en Caja aparece Dólares en caja. El admin puede fijar el tipo de cambio a mano por el día en Ajustes. La forma de pago está a la vista en el ticket, abajo de los totales. Se pueden combinar varios medios (por ejemplo parte en efectivo y parte con Point).',
      pasos: ['El renglón arranca sin medio elegido (así la factura no se emite sin querer): hay que elegirlo en el desplegable (cada uno con su ícono: billetes para efectivo, tarjeta, celular para Point, etc.; al elegirlo el ícono hace un saltito) y el importe. Mercado Pago Point y QR aparecen una sola vez: abajo del renglón sale una pastilla partida Integrado | No integrado, con Integrado por defecto; si el cobro se hizo fuera de la integración, tocá "No integrado". Con un solo renglón el importe se sugiere solo con el total. Para pagos combinados (parte efectivo, parte tarjeta) tocá el "+" al final del primer renglón: el renglón nuevo trae lo que falta.', 'Tarjeta, link, transferencia y vale piden una referencia (número de cupón, etc.).', 'Si en efectivo cargás más que el total, abajo aparece el Vuelto y la venta queda registrada por el total.', 'El botón de abajo dice qué va a emitir (factura B, A, manual o NC) y se habilita cuando lo pagado cubre el total. Al emitir aparece el comprobante: la factura y la nota de crédito electrónicas se imprimen en la comandera desde el ícono de la impresora (logo, local, detalle, QR y CAE de ARCA, datos fiscales y contacto al pie; en Atelier Libertador sale el logo con la firma Atelier). La factura manual y el presupuesto no se imprimen: quedan en pantalla y en Comprobantes. Además, de cada comprobante emitido se arma solo un PDF en hoja A4 (el que va por mail al cliente, con la foto de cada artículo): aparece el botón PDF en el comprobante y en la lista de Comprobantes apenas está listo (las facturas electrónicas, en cuanto tienen CAE). Los medios de pago son los mismos códigos que el Dragonfish (efectivo, MP Point, QR, tarjeta…), así Ventas los suma igual.'] },
    { icon: '🔐', titulo: 'Autorizaciones', desc: 'Todos entran con el usuario genérico del local y ven todas las funciones. La nota de crédito, el comprobante X rojo, el remito y la anulación piden autorización de una persona de rango mayor: encargada, cajera (rango nuevo) o admin, siempre una persona con legajo, nunca el genérico. Al tocar Emitir aparece la ventanita con quiénes están en el local ahora (según el reloj de fichadas de hoy; si todavía no subió, el turno planificado en RRHH): tocás Pedir a esa persona y le llega un aviso al celu (app RRHH) con Aceptar y Rechazar; cuando acepta, el comprobante sale solo. Si no hay nadie, se le puede pedir a un admin. Si no tienen el celu a mano, en la misma ventanita cargan usuario y clave. La autorización vale 10 minutos, para ese solo comprobante, del mismo local; la traba está en la base. En Comprobantes queda quién autorizó y cómo (push o clave). Una encargada, cajera o admin logueada con su propio usuario emite sin pedir nada. El admin asigna los rangos en Ajustes.' },

    { icon: '🧾', titulo: 'Comprobantes', desc: 'Lista de lo emitido en el local por rango de fechas, con filtro por tipo y buscador por cliente, número o vendedora. Las fechas arrancan en hoy. «Desde» vacío trae todo para atrás y «Hasta» vacío todo para adelante (los dos vacíos: todo); como mucho se muestran los 500 comprobantes más nuevos, y si se llega a ese tope arriba lo avisa. Para abrir un comprobante se toca su número (Factura B 0003-…), como en Pedidos; ya no hay botón del ojo. El buscador encuentra por cualquier cosa: cliente, documento, número, artículo (código o descripción), forma de pago (efectivo, Point, QR, transferencia…), referencia del pago, vendedora, quién atendió o autorizó, CAE, observaciones, dirección de entrega o importe (45000, 45.000 o $45.000 coinciden con el total, con un pago o con un artículo). Si se escriben varias palabras, tienen que estar todas (por ejemplo «point 45000» o «velas maria»); no importan tildes ni mayúsculas. Busca dentro de las fechas elegidas (vacías: todo). En Remitos el buscador funciona igual, y el número del remito también es el enlace para abrirlo (sin el ojo). Clodi también busca: se le puede pedir «buscame la factura de María Pérez», «¿a quién le vendimos velas Fichi esta semana?» o «la venta de 45000 con Point de ayer»; llena el buscador y las fechas, y contesta qué encontró (los primeros cinco, con número, fecha, cliente e importe). No manda ni cambia nada. Se ve con las mismas pestañas que la vista previa: Comandera (ticket) y Hoja A4, más el PDF si ya está armado; el botón de imprimir imprime la pestaña que se está viendo.',
      pasos: ['El ojo abre el comprobante y permite imprimirlo de nuevo.', 'Usuarios con el POS acotado: un admin puede dejarle a una persona solo algunas pestañas del POS. Por ejemplo, el usuario del depósito ve solo Remitos, Pedidos y Etiquetas: no tiene Vender, Comprobantes, Vales ni Caja, y el sistema tampoco le deja emitir facturas ni notas de crédito, solo remitos. Si a alguien le falta una pestaña que necesita, lo cambia un admin.', 'Seña con descuento: en el cuadro «Artículos señados», cada artículo tiene una casilla de descuento ($ o %). Un número son pesos por unidad; con % al final es porcentaje. El precio del artículo queda congelado ya con ese descuento: cuando el cliente vuelve y se usa la seña, el artículo entra al ticket a ese precio.', 'Ver un pedido ya hecho: en Pedidos → «Pedidos hechos», el ojo (o tocar el número del pedido) abre el pedido completo: a quién se pidió, quién lo pidió, el estado, cada artículo con su foto y cantidad, lo que llegó, la nota, y los botones de PDF y Excel. Lo puede abrir cualquiera del local, también el usuario genérico; es solo para mirar, no pide autorización.', 'Movimientos de stock: entre los motivos fijos está «Retiro de mercadería personal», para la mercadería que se lleva una colaboradora y después se le descuenta del sueldo. Filtrando Movimientos por ese motivo se ve todo lo retirado.', 'Presupuesto (con el tilde «Presupuesto»): sale con la leyenda «Los precios de este presupuesto se mantienen por 14 días corridos», con la fecha hasta la que valen, en la comandera, en la hoja A4 y en el PDF que se manda por mail.', 'Tarjeta de regalo (la de la página web): no es la «Gift card» digital. Es un artículo común con el código TARJETA DE REGALO: en Vender se escribe «tarjeta» o «regalo» en el buscador, se agrega al ticket y se le pone el importe a mano cada vez (no tiene precio fijo). No genera código ni vale, no manda nada al cliente y no mueve stock. La «Gift card» digital (escribiendo «gift») sigue igual: esa sí genera el código y se manda por mail o WhatsApp.', 'Numeración cuando facturan varias a la vez: el número de la factura no se toma al abrirla sino en el momento de tocar Emitir, de a una por punto de venta. La que emite primero se lleva el número más bajo, aunque haya empezado a cargar después. No puede haber dos facturas con el mismo número ni quedan huecos: si una emisión falla, su número queda libre para la siguiente.', 'Factura «En espera»: ARCA autoriza los números en orden. Si ARCA rechaza una factura (por ejemplo por un CUIT mal cargado), las que se emitan después en ese punto de venta quedan con la etiqueta «En espera» (al pasar el mouse dice cuál es la factura que las frena). No hay que hacerles nada: apenas se corrige y se reintenta la rechazada, las que estaban en espera piden su CAE solas, en orden.', 'La flecha hacia atrás arma la nota de crédito de esa factura: te lleva a Vender con sus artículos cargados para sacar lo que no vuelve y elegir cómo se devuelve la plata. La NC lleva la misma letra que la factura; una devolución de una factura manual sale como NC manual.', 'Anular (solo encargada o admin) deja el comprobante tachado con el motivo; no se puede anular si ya tiene notas de crédito. Los comprobantes electrónicos (factura, nota de crédito o nota de débito A o B) no se anulan nunca una vez que están en ARCA o se están informando: no aparece el botón de anular y el sistema lo rechaza, porque lo del POS tiene que coincidir 100 % con lo que ARCA tiene; se corrigen con una nota de crédito. Solo se puede anular el electrónico que ARCA rechazó (queda en rojo «CAE rechazado», nunca llegó a ARCA) y los comprobantes que no van a ARCA: X, remitos y presupuestos.', 'Estados: "CAE…" = la factura ya salió y el sistema le está pidiendo el CAE a ARCA (tarda unos segundos; el ticket se actualiza solo y aparece el QR de ARCA); "CAE" = autorizada; "CAE rechazado" = ARCA no la aceptó: el motivo está al pasar el mouse y la flecha ↺ la vuelve a pedir (encargada o admin). "Manual" = factura manual.'] },
    { icon: '📦', titulo: 'Pre-remito: guardar el remito sin emitir', desc: 'El remito tiene tres estados: Pre-remito, En tránsito y Aceptado (son las tres pastillas de la pestaña Remitos). El pre-remito es una proforma: sirve para cuando en el depósito se separa la mercadería, se embala, se agregan cosas en el mismo día y recién al final se cuentan los bultos. Se guarda sin número, sin CAI y sin mover el stock: no es un remito oficial.',
      pasos: ['En «+ Remito» se arma como siempre (destino, mercadería, transporte, nota). Si todavía no está todo, se toca «Guardar pre-remito» (al lado de Emitir): queda en Remitos → Pre-remitos.', 'En Pre-remitos se ve cada uno con su número interno, a dónde va, la mercadería, cuándo se guardó y quién. Se toca «Seguir armando» (o el renglón) y se abre con todo lo cargado para agregar o sacar.', 'Se puede volver a guardar las veces que haga falta.', 'Cuando está todo embalado: se abre, se pone la cantidad de bultos y se toca «Emitir remito». Ahí recién sale el remito R oficial, baja el stock y, si va a otro local, empieza el tránsito; el pre-remito sale de la lista.', 'Si no se va a mandar, el tacho lo descarta (no había movido stock).', 'La vista previa (el ojo) muestra cómo va a salir la hoja del remito, por si hace falta imprimirla como lista para preparar.'] },
    { icon: '🧾', titulo: 'La hoja del remito R: todo lo que pide ARCA', desc: 'Desde el 19-nov-2026 el remito es «R» con CAI (antes era X, que ARCA solo acepta dentro de un mismo predio). La hoja tiene la madera arriba con el logo, la R en un recuadro con el código 091, el número de 13 dígitos (por ejemplo 00039-00000001), la fecha de emisión y si es ORIGINAL o DUPLICADO. Abajo de la madera van los datos de Claudia Adorno SRL (CUIT, IVA, ingresos brutos, inicio de actividades y domicilio), y en tres cajitas: destinatario, lugar de entrega y transportista. Al pie: bultos, unidades, valor de la mercadería, las firmas (entregó y recibí conforme), «Documento no válido como factura», el CAI con su vencimiento y el COT si corresponde.',
      pasos: ['Se imprime en dos hojas: el ORIGINAL viaja con la mercadería para quien la recibe y el DUPLICADO queda en Claudia Adorno (se guarda dos años).', 'El destinatario sale según su condición frente al IVA: en un traslado entre locales, Claudia Adorno SRL con su CUIT; a un consumidor final, la leyenda «A CONSUMIDOR FINAL» con el nombre y el DNI; a un responsable inscripto, monotributista o exento, el nombre, el CUIT, la condición y el domicilio (de la ficha del cliente).', 'A un proveedor: además del nombre se pone su CUIT. Familia García y Espalma lo traen solo; para otro proveedor se escribe el CUIT y el POS completa la razón social, la condición y el domicilio con el padrón de ARCA.', 'Transportista: se elige de la lista. Familia García Regueira lleva su CUIT y su domicilio (los pide ARCA cuando lleva un tercero); el flete propio no los necesita. Si se escribe otro transportista a mano, la hoja avisa que falta su CUIT.', 'COT: es el código de traslado de ARBA (provincia) o AGIP (Ciudad), aparte del remito. Si corresponde, se escribe el número en «N° de COT» y sale en la hoja.', 'En modo prueba la hoja dice PRUEBA · SIN VALOR FISCAL y no lleva CAI.'] },
    { icon: '🚚', titulo: 'Remitos', desc: 'Remito de venta: la mercadería sale sin cobrar (entrega a domicilio, cliente que factura después). «+ Remito» abre el remito nuevo en una ventana encima de la lista (se cierra con la cruz, con Escape o tocando afuera, y no emite nada); usa el mismo buscador y ticket de Vender, con un color según a quién va (violeta si es a otro local, ámbar si es a un proveedor y naranja si es a un cliente): cliente obligatorio, dirección y nota de entrega opcionales, sin pagos ni CAE; es un remito R con el CAI del local (ver «La hoja del remito R» y «CAI de los remitos»). Al emitir baja el stock, se imprime en A4 con el logo para que viaje con la mercadería y, si el cliente tiene mail, se le manda. La lista muestra los remitos del local: Sin facturar o Todos, con el estado (sin facturar, facturado con el número de la factura, anulado). Facturar (desde acá, desde Comprobantes o al cargar el cliente en Vender) arma la factura con los artículos ya entregados y no descuenta de nuevo. Anular un remito devuelve la mercadería al stock; si ya se facturó no se puede anular: hay que anular o devolver la factura. El remito tiene tres destinos, en este orden: «A otro local» (viene elegido, es lo más usado), «A un proveedor» y «A un cliente». A un proveedor: para devolver mercadería o mandar mercadería defectuosa; elegís Familia García o Espalma de la lista o escribís el nombre de otro proveedor, ponés el motivo en la nota y emitís: baja el stock del local, no cobra y el remito sale a nombre de «Proveedor: …»; ese remito no se factura. Mercadería en tránsito: en «+ Remito» elegís A otro local, el destino y una nota para el transporte; al emitir baja del stock de este local y queda en tránsito (la encargada del destino recibe un aviso al celu). La pastilla En tránsito muestra, con un contador, lo que viene a este local y lo que este local mandó, con su estado: en tránsito, recibido (por quién y cuándo) o recibido con diferencia. Recibir es tarea de la encargada: cuenta renglón por renglón lo que llegó (lo enviado al lado), puede dejar una observación y acepta; lo aceptado entra al stock en ese momento y lo que falta queda marcado en rojo para que el origen lo resuelva (lo manda en otro remito o lo da de baja con un movimiento manual). Un traslado ya recibido no se anula. Lo que otros locales le piden a este ya no está en Remitos: pasó a la pestaña Pedidos, pastilla «Me piden» (con contador). Ahí aparece lo que otros locales le pidieron a este, una tabla con un renglón por pedido, el más nuevo arriba (los títulos ordenan y filtran como en Excel): número del pedido, local que pide, quién lo pidió, fecha y hora, cuántos artículos y unidades, y la nota si la tiene. Arriba hay tres pastillas: «Todos», «Sin preparar» (pedidos que todavía nadie tocó) y «Preparando» (los que ya tienen algo marcado). Tocando un pedido se abre con todo lo que piden: cada artículo con su foto, la cantidad pedida y cuánto hay acá. En cada artículo se marca «✔ Embalado» si lo tenés y ya lo preparaste, o «✖ No hay» si no lo vas a mandar: ese queda tachado y fuera del pedido. Tocar de nuevo la misma pastilla la desmarca. «Marcar todo embalado» marca de una lo que falta ver. Con «Armar el remito con lo embalado» se abre el remito de traslado ya cargado solo con lo embalado (destino, artículos, cantidades y nota con el número del pedido); lo que quedó sin ver sigue en «Me piden» para un remito posterior. Lo que se pidió desde el módulo Stock, sin pedido del POS, aparece como «Pedido suelto», agrupado por local y por día. El contador de la pastilla «Me piden» cuenta pedidos, no artículos; al emitirlo los pedidos quedan enviados y apuntan al remito. Si algo ya salió sin remito, el tilde cierra el pedido sin mover stock. En todo remito (a otro local, a un proveedor o a un cliente) es obligatorio completar la cantidad de bultos: sin ese dato no deja emitir; sale en el remito como «Bultos: N» junto con la observación y se ve en En tránsito. Cuando la encargada recibe mercadería en tránsito, cada artículo recibido queda como un movimiento de stock («Recibido de un traslado») y aparece en la lista de Movimientos, con el enlace al remito. Etiquetas: cada movimiento de entrada tiene el botón de la impresora, que lleva a Etiquetas con ese artículo y esa cantidad ya cargados; y cada remito (en Sin facturar, Todos y En tránsito) tiene el mismo botón, que carga todos los artículos del remito. Es optativo: se usa cuando hace falta etiquetar. Pastillas de Remitos: «En tránsito» (traslados que el destino todavía no aceptó, y los rechazados, que quedan en tránsito de vuelta hasta que el local que los mandó toca «Aceptar la vuelta»: recién ahí la mercadería entra de nuevo a su stock; no hay rechazo que quede en el aire), «Aceptados» (traslados que el destino ya aceptó y entraron al stock, con quién los recibió y si hubo diferencia; los rechazados que ya volvieron; y los remitos que no tienen otra punta, como los que van a un cliente o a un proveedor, que quedan aceptados desde que se emiten y, si falta facturarlos, traen el botón para hacerlo) y «Movimientos». En el renglón de cada remito en tránsito están el ojo (abre el remito; desde ahí se imprime) y, según el caso, «Aceptar» y «Rechazar» para el local que recibe, o corregir y anular para el local que lo mandó. Recibir mercadería en tránsito: en En tránsito, tocando el renglón del remito se despliega abajo la mercadería que viene (foto, código y cantidad). El local que la recibe tiene tres botones: «Confirmar: llegó todo» (entra al stock en ese momento), «Llegó con diferencia» (se cuenta lo que llegó y lo que falta queda marcado) y «Rechazar». Rechazar pide siempre el motivo: la mercadería no entra y queda en tránsito de vuelta hacia el local que la mandó; a ese local le llega el aviso al celu con el motivo y el remito le aparece en «En tránsito» como «Rechazado · vuelve a …» con el botón «Aceptar la vuelta». Cuando lo toca, la mercadería entra de nuevo a su stock y el remito pasa a «Aceptados» como «Rechazado y devuelto». Confirmar y rechazar los hace la encargada; desde el usuario genérico piden su autorización (cámara, celu o clave). Si llegó menos de lo que decía el remito («Llegó con diferencia»): lo que llegó entra al stock del local que recibe, y lo que NO llegó no desaparece: queda en tránsito de vuelta al local que lo mandó, al que le llega un aviso al celu. Ese remito le aparece al local de origen en «En tránsito», con la marca «falta resolver», y tiene dos botones: «Volvió al stock» (la mercadería estaba ahí: vuelve a su stock) y «Faltante» (no aparece: se da de baja). Los dos abren una ventana donde se elige uno de los motivos fijos de Movimientos (Inventario, Rotura, Faltante, Error de carga…) y se escribe la observación (obligatoria si es faltante), y piden la autorización de la encargada. En los dos casos queda el movimiento de stock anotado en Movimientos, con el motivo elegido, la observación y el remito y el tránsito a los que corresponde, así se puede filtrar por motivo: «Volvió al stock» deja una entrada; «Faltante» deja la entrada de lo que volvió del tránsito y la baja como faltante. Esos movimientos no se anulan ni corrigen a mano. Hasta que el origen lo resuelve, el remito sigue contando en el numerito de «En tránsito». Y al revés, si llegó DE MÁS (el remito decía 1 y llegaron 2): en «Llegó con diferencia» se anota lo que llegó de verdad; entra todo al stock del local que recibe, y al local que lo mandó le llega el aviso y le aparece el remito en «En tránsito» con el botón «Dar de baja el sobrante», que descuenta de su stock lo que salió sin anotar. Mientras el destino no la aceptó, el local que emitió el remito de traslado puede anularlo (la mercadería vuelve a su stock) o corregirlo: «Corregir» anula ese remito y abre uno nuevo con los mismos artículos, destino y bultos para cambiar lo que haga falta y emitirlo otra vez. Una vez que el destino la aceptó (o la rechazó) ya no se puede anular ni corregir. El remito se imprime solo en hoja A4 (no sale por la comandera: la vista previa abre directo en A4) y se titula «Remito X», con el destino, la cantidad de bultos y la leyenda «no válido como factura». En el remito hay una casilla opcional «Quién lo transporta»: al tocarla ofrece los dos de siempre (Familia García Regueira con su chofer Néstor Donzelli, y Richard Soto, el flete propio) y también se puede escribir otra cosa, por ejemplo un flete tercerizado. No es obligatoria. Sale en la hoja del remito y se ve en En tránsito. Números únicos: cada remito se identifica con el local adelante (por ejemplo ALC 0002-00000015 es de Alcorta y UNI 0002-00000015 es otro, de Unicenter), y cada mercadería en tránsito tiene además su propio número, que no se repite nunca (por ejemplo TR-000062). Los dos aparecen en En tránsito, en Aceptados y en la hoja del remito. En la lista de Movimientos, todo lo que salió o entró por un traslado («Salió por traslado» / «Entró por traslado») muestra a qué remito y a qué tránsito corresponde, con el trayecto; tocando el número se abre el remito, y el buscador encuentra por cualquiera de los dos números. El remito no lleva descuentos (no tiene columna de descuento ni descuento general) y la nota va en la casilla Observación de abajo: no hay una casilla aparte de nota para el transporte. Movimientos (misma pestaña): entradas, bajas y ajustes de stock hechos a mano; los hace la encargada o, desde el usuario genérico del local (o el de la cajera), con la autorización de la encargada: al guardar aparece el cartel de autorización, se le pide al celu (o autoriza ahí con su clave); cada movimiento pide su propia autorización, igual que cada remito (la autorización que sirve para varias cosas seguidas durante 15 minutos es solo la de pedidos y mínimos); la cajera no autoriza movimientos, solo la encargada o un admin; queda anotado quién autorizó: botón «+ Movimiento» (arriba, al lado de «+ Remito») → Entrada (unidades que entran), Baja (unidades que salen) o Ajuste a (el stock que tiene que quedar), el producto, la cantidad y el motivo, que se elige de una lista fija (Inventario, Rotura, Ingreso de mercadería, Muestra, Uso interno, Regalo o cortesía, Devolución a proveedor, Faltante, Error de carga, Otro) con un detalle opcional; con «Otro» el detalle es obligatorio. Si alguien se equivocó al cargar un movimiento, cada renglón tiene dos botones: anular (el círculo tachado) y corregir (el lápiz). Los dos piden siempre el motivo y la autorización de la encargada. Anular restablece el stock y deja el renglón en la lista, atenuado y con la marca «Anulado», quién lo autorizó y el motivo: nada se borra. Corregir anula ese movimiento y abre uno nuevo ya cargado con lo mismo, para cambiar lo que esté mal y guardarlo (el nuevo pide su propia autorización, como todo movimiento). Un movimiento anulado no se puede volver a anular ni corregir. En la lista de Movimientos, la fila de pastillas «Motivo» filtra por cada uno y trae toda la tirada de ese motivo con la cantidad de movimientos y las unidades netas: por ejemplo todo lo ajustado en un inventario. «Traslado» muestra lo recibido de otro local; los movimientos viejos con motivo escrito a mano aparecen en «Otro». Queda en el libro con quién y por qué, y se ve en el historial de la ficha. Hasta el cierre del año el stock en pantalla sigue siendo el del Dragonfish; después el movimiento lo cambia al instante.' },

    { icon: '📋', titulo: 'La hoja del pedido: planilla de control', desc: 'Desde el 19-nov-2026 el PDF del pedido es distinto de la factura para que no se confundan: arriba una franja gris azulada con el logo, «Pedido de mercadería» y el número grande (por ejemplo UNI-00010), la versión y la fecha; debajo, en un recuadro, a quién se le pide, dónde se entrega, las consultas y el total de unidades.',
      pasos: ['Los artículos van numerados, con la foto, la descripción, el código y la cantidad, y al final de cada renglón un círculo para tildarlo al recibirlo.', 'En una versión modificada lo que cambió va primero y en negrita (con «antes 10», «nuevo» o «se sacó»), y arriba un cartelito naranja explica que reemplaza a la versión anterior.', 'Al pie: cuántos artículos y unidades, y las firmas «Preparó» y «Controló al recibir».', 'Entran 15 artículos por hoja; la última lleva los totales y las firmas.'] },
    { icon: '📦', titulo: 'Pedidos', desc: 'IMPORTANTE: desde el 12 de noviembre los Pedidos son reales, aunque el resto del POS siga en ambiente de prueba (el cartel rojo de arriba lo avisa: «los PEDIDOS sí son reales»). A quién le llega cada pedido (desde el 13 de noviembre): un pedido a Familia García Regueira sale por mail, con el PDF y el Excel, a sucursales@claudiaadorno.com con copia a claudiaadorno@claudiaadorno.com, y además le llega una notificación al celular de Rivera. Un pedido a Oficina le llega al depósito: mail con el PDF y el Excel al mail personal de Iván y a claudiaadorno@claudiaadorno.com (Rivera), y notificación al celular de Iván y de Rivera. WhatsApp: ya no va a un número fijo. Al terminar el pedido (y también después, desde «Pedidos hechos», con el botón de WhatsApp del pedido) aparece el texto listo y una casilla para escribir el número al que se lo querés mandar, con código de área y sin 0 ni 15; el POS recuerda el último número que escribiste en esa computadora para cada destino. Mandarlo por WhatsApp es opcional: el mail sale igual. en el depósito lo ven en su POS en Pedidos → «Me piden». Mientras los remitos se sigan haciendo en el Dragonfish, el local recibe la mercadería en Mercadería → Remitos → «En tránsito» (los traslados de Oficina con «Aceptar» y los pedidos a Familia García, cuando ya llegó su remito, con «Recibir»). En «Pedidos hechos» ya no hay botón de recibido. Los pedidos a Espalma todavía no tienen mail cargado: hasta que se cargue no sale mail, solo el WhatsApp al número que se escriba. Un pedido enviado se MODIFICA con el lápiz de «Pedidos hechos» (desde el 18-nov reemplaza a «Descontar»): se cambian cantidades, se saca un artículo con la cruz o se suma uno nuevo. Al mandarlo sale la VERSIÓN SIGUIENTE del mismo pedido (mismo número, v2, v3…) con el pedido COMPLETO, y la versión anterior queda anulada («Reemplazado por la versión 2»); le llega al proveedor (o al depósito) por mail y WhatsApp como un pedido más. Lo que se agregó o se sacó va PRIMERO y en NEGRITA en la ficha, el PDF y el Excel, con lo que era antes («nuevo», «antes 6», «se sacó · eran 6»). Se puede modificar mientras el pedido está pendiente; si Familia García ya lo facturó (en tránsito) o el depósito ya lo despachó, ya no. Cancelar un pedido entero solo lo puede hacer un admin. En «Qué falta», las columnas van: Otras sucursales, Stock, En tránsito, Ya pedido, Mínimo, Falta y Pedir. Pedidos del local (la pestaña no aparece cuando el POS está en Oficina: los pedidos de Oficina a proveedores van por el módulo Compras). Qué falta: para cada producto con mínimo muestra stock, en tránsito hacia el local, ya pedido, mínimo y falta (mínimo menos todo lo demás, nunca negativo), agrupado en Familia García Regueira (se le pide al proveedor) y Oficina (depósito, lo que Oficina ya compró, con cuánto tiene). Arriba, las pastillas Todos / Familia García / Espalma / Oficina filtran a quién se le pide (con la cantidad de artículos de cada uno): elegís Familia García, Marcar todos y armás ese pedido; después Espalma, y después Oficina. Hay tres destinos: Familia García Regueira y Espalma son proveedores a los que el local les pide directo (el pedido sale por mail en PDF y en Excel; el mail de cada uno se carga en Ajustes); todo lo demás se le pide al depósito de Oficina, y dentro de Oficina la lista viene ordenada y separada por proveedor. En «Qué falta» se elige a quién se le pide con las pastillas Familia García Regueira, Oficina o Espalma, en ese orden (viene elegida Familia García Regueira): se ve de a uno por vez, porque cada pedido va a un solo destino y nunca se mezclan. El mínimo y el «pedir desde» se pueden cambiar sin salir de «Qué falta»: son casillas; se escribe el nuevo valor y el renglón se pinta de amarillo, sube arriba de todo y se recalcula lo que falta, sin perder lo que ya estaba tildado ni las cantidades cambiadas. Quedan pendientes hasta tocar «Guardar N cambios» en el título de la tabla, que los guarda todos juntos con una sola autorización (20-nov). La pestaña Mínimos sigue estando para cargar o revisar todos juntos. Quién puede: en el local queda siempre abierto el usuario genérico. Armar, cancelar o recibir un pedido y cargar o cambiar un mínimo necesitan la autorización de la encargada, la cajera o el admin: al enviar el pedido (o al tocar «Guardar N cambios» de los mínimos) aparece el cartel con quiénes están en el local, se elige a quién pedírselo y le llega la notificación al celu para aceptar o rechazar; si no tiene el celu a mano, autoriza ahí mismo con su usuario y clave. La autorización vale 15 minutos y sirve para varias cosas seguidas del mismo tipo (los pedidos de un armado), así no se pide una por una; los mínimos se autorizan todos juntos al guardarlos. Si quien está logueada ya es encargada, cajera o admin, no pide nada. En cada pedido y en cada mínimo queda anotado quién lo autorizó. Los artículos dados de baja (los que tienen el tilde «importado» en el Dragonfish, que es la marca de lo que ya no se trabaja) no aparecen en Qué falta ni en Mínimos, y tampoco se pueden agregar a mano a un pedido. Pedir algo que no está en la lista: en la barra de «Qué falta», el botón «Fuera de lista» abre una ventana para sumar al pedido del proveedor que se está viendo un artículo del sistema (por código o descripción) o un renglón libre para lo que no está en el sistema (resma de papel, cinta, lapiceras), cada uno con su cantidad. Lo sumado queda guardado (el botón muestra cuántos hay) y entra en el pedido al tocar «Armar pedido», junto con lo tildado, o solo si no se tildó nada. El pedido que se está armando se guarda solo (19-nov): lo tildado, las cantidades que se cambiaron, lo de fuera de lista y la nota quedan guardados al instante en la compu y al segundo en el sistema, uno por destino (Familia García Regueira, Oficina y Espalma). Si se cierra la ventana, se corta la luz o internet, se va a vender y se vuelve, o la sigue otra chica en otra compu del mismo local, al entrar a «Qué falta» está todo como quedó. Arriba de la lista aparece el cartel «Pedido a medio armar», con cuántos artículos hay tildados, quién lo empezó y quién lo tocó por última vez, y la pastilla del destino tiene un puntito naranja. Lo tildado se sigue viendo aunque ya no esté bajo mínimo, y entra en el pedido aunque la búsqueda lo esconda. Lo guardado se borra solo cuando se envía el pedido; para tirarlo antes está el botón «Empezar de cero» del cartel, que pide confirmación y lo vacía en todas las compus del local. Si sale «Sin conexión», quedó guardado en esa compu y se sube solo cuando vuelve internet. Si dos compus tocan el mismo pedido a la vez, no se pisan: la segunda ve un aviso y la lista como quedó, y si el pedido ya lo envió otra compu, no se vuelve a armar (así no sale dos veces). Lo que se cambia en la ficha del pedido (la ventana de «Armar pedido») es solo para ese envío, salvo la nota, que también se guarda. La ficha del pedido ya no tiene casillas para agregar: muestra los artículos con su cantidad, la nota para el proveedor y cómo sale. El pedido al proveedor (Familia García o Espalma) sale siempre en PDF y en Excel, los dos adjuntos en el mismo mail; en Pedidos hechos están los dos para abrir o bajar. La columna «Otras sucursales» muestra cuánto stock hay del mismo artículo en los demás locales (en verde) y en la oficina (en gris, con el rótulo «Administración»), para ver si conviene pedírselo a otro local antes que al proveedor; si dice «no hay en otro lado» nadie tiene. Artículos con desglose (los que vienen juntos del proveedor, como el cesto de ropa recto grande y chico): aparecen juntos, con fondo naranja clarito y el cartel «Vienen juntos del proveedor», aunque a uno solo le falte stock y aunque el otro no tenga mínimo cargado; así no se deja de pedir el juego porque sobra de uno. El juego tiene una sola casilla de cantidad a la derecha, que vale para todos sus artículos (se pide esa cantidad de cada uno), y se marca o desmarca entero. Filtro Bajo mínimo; la columna Pedir viene con lo que falta y se puede cambiar; marcás y Armar pedido abre un pedido por destino. A Oficina: se crean los pedidos de traslado, Oficina los ve en su POS en Pedidos → Me piden, arma el remito con un clic y entran por En tránsito (aviso al celu de la encargada de Oficina). A Familia García: lista para controlar, nota, y al enviar sale el mail con el PDF y el Excel (casilla y copia en Ajustes) y queda el texto listo para mandarlo por WhatsApp al número que se escriba; después se marca Recibido cuando llega (el stock entra con la compra o un movimiento manual). Mínimos: la encargada escribe el mínimo de cada producto para su local (cero lo saca); los cambios quedan pendientes, arriba de todo, y se guardan juntos con «Guardar N cambios»; hasta el cierre del año los que no se tocaron vienen del Dragonfish y los cargados acá no se pisan. Pedidos hechos: cada pedido con estado (pendiente en Oficina, en tránsito con su remito, recibido, pendiente de entrega con mail y WhatsApp, cancelado).' },

    { icon: '🏷', titulo: 'Etiquetas', desc: 'Imprime la etiqueta de producto con el diseño C1 elegido el 30-oct: QR con el SKU a la izquierda (lo que leen los lectores de caja), el SKU grande, Claudia Adorno pegado debajo del SKU y la página claudiaadorno.com abajo, en el rollo de 3 bandas de 31,7 × 12,7 mm. La cantidad va primero: escribís 12 y + (o 12+) y Enter, y después escaneás o escribís el SKU: entra con 12; también todo junto, 12 SMINI. Sin cantidad entra de a una, y en la cola se corrige. A la derecha se ve en vivo cómo queda el rollo, tal cual se lee la tira con el texto derecho: la A arriba a la izquierda y la Z abajo (por eso la etiquetadora imprime primero la Z: lo primero que sale queda en la punta de abajo); también desde la ficha del producto (Etiquetas ›) y desde En tránsito, el botón de imprimir en un traslado recibido carga lo que llegó. Con el POS en Oficina aparece el botón «Desde remito»: muestra los remitos de venta del Dragonfish de Oficina de los últimos 10 días (se actualizan solos cada medio minuto), con buscador por número o destino. Tocando uno, todos sus artículos entran a la lista de etiquetas con la cantidad del remito; se puede corregir o sacar alguno antes de imprimir. Es provisorio, mientras los remitos se sigan haciendo en el Dragonfish. Imprimir desde el celular en los locales: cada local imprime solo en su propia etiquetadora y solo estando en el local. El POS lo comprueba solo: si el celular está en el WiFi del local, imprime directo; si está con datos móviles, pide permiso para ver la ubicación y deja imprimir si está en el shopping. Desde afuera avisa que hay que estar en el local. Los admin imprimen desde cualquier lado. Las etiquetadoras se ven en Ajustes → «Etiquetadoras» (solo admin): estado, oscuridad, y el alta de la PC de cada local con el código de 6 números que muestra esa PC. La vista previa del rollo está siempre a la derecha y se actualiza sola. En «Rollo» está «Sentido»: «Girada 180°» (lo normal) o «Sin girar», por si en alguna impresora las etiquetas salen patas para arriba; la vista previa siempre se ve derecha. El botón «Imprimir» manda las etiquetas directo a la etiquetadora del local en el que está el POS, sin cuadro de impresión y sin elegir impresora: por eso se puede imprimir también desde el celular o la tablet. Debajo del botón dice por qué etiquetadora sale; si aparece «sin conexión», la PC que imprime está apagada y las etiquetas salen cuando vuelva. Al mandar, la lista se vacía sola y el POS avisa cuando quedaron impresas. Si un local tiene dos etiquetadoras (una común y una RFID), el POS separa solo: cada artículo va a la etiquetadora que le corresponde. «Desde esta PC» imprime por el cuadro de Windows eligiendo la impresora a mano, por si hace falta. Hoy está conectada la etiquetadora del depósito (con el POS en Oficina); en un local que todavía no la tiene conectada, «Imprimir» abre el cuadro de Windows como antes. El rollo (ancho, alto, cuántas por fila, separación, margen y nombre) se configura a la derecha y queda guardado en esa computadora; el de siempre es 31,7 × 12,7 mm, 3 por fila, 3,2 mm entre bandas y 2,5 mm de margen. Cualquiera puede etiquetar. También se le pueden pedir a Clodi, escritas o por voz: «imprimime 10 etiquetas de la SMINI» o «necesito 3 de la SMINI y 5 de la ACRISD» (19-nov). Clodi abre Etiquetas y deja la lista armada con esas cantidades (si ya había una lista, pregunta antes de vaciarla); no imprime sola: mirás la lista y la vista previa del rollo y recién al tocar «Enviar» en el cartel de Clodi (o «Imprimir») salen por la etiquetadora del local, con los mismos controles de siempre. Si no encuentra un código, lo avisa y no carga nada. Si no salen (por ejemplo, desde un celu en un local sin etiquetadora conectada), Clodi lo dice y la lista queda armada. Las etiquetas RFID nuevas (impresora Chainway) van por su propio circuito.' },

    { icon: '％', titulo: 'Promociones', desc: 'Acá se cargan las promociones que el POS aplica solo en Vender. Las ven todos (locales, encargada, cajera, vendedora y el usuario genérico). Las cambian el admin y la oficina: Rivera y Contreras solas; el usuario genérico de Oficina pide la autorización de Rivera, Contreras o el admin. Cualquier cambio (crear, modificar, cambiar las fechas, pausar, reactivar o dar de baja) queda en el historial con quién lo hizo y quién lo autorizó.',
      pasos: ['La lista muestra cada promoción con qué hace, a qué artículos se aplica, cuándo y en qué locales, el estado (Activa, Programada, Pausada, Vencida o Dada de baja) y cuántas veces se usó. El filtro de arriba elige qué estados ver y el buscador encuentra por nombre, artículo, categoría o local.', 'Tocando el nombre se abre la ficha. Quien puede cambiarla la edita ahí mismo y toca «Guardar los cambios»; el resto la ve sin poder tocar nada.', '«＋ Nueva promoción»: poné el nombre, elegí el tipo, completá «Cómo funciona», elegí a qué artículos (todos, o combinando Nivel 1 (grupo), Nivel 2 (categoría), Nivel 3 (clasificación), proveedor, material, origen, temporada, línea y «La descripción dice»; «Y además» suma artículos sueltos y «Menos» excluye algunos), cuándo (desde, hasta, días de la semana y horario: vacío = sin límite) y dónde (locales: ninguno = todos; tope de unidades por ticket). Arriba de la ficha se va leyendo cómo queda.', 'Tipos: Lleva N, paga M (2x1, 3x2, 4x3, 4x2: de cada N se pagan las M más caras) · Unidad N con descuento (2ª al 50 %, 3ª gratis: la más barata de cada grupo) · Por cantidad (escalones: desde 3 u. 10 %, desde 6 u. 20 %) · Combo a precio fijo (3 por $ 100.000) · Descuento directo (20 % en una línea) · Pesos menos por unidad · Precio especial (cada uno a $ X) · Lleva y se regala (con 2 de A, 1 de B gratis) · Lleva A, descuento en B (con un mantel, 30 % en vajilla) · Por monto de compra (desde $ X, un % o un monto) · Por forma de pago (15 % en efectivo).', 'A qué artículos: las variables se COMBINAN, tiene que cumplir todo lo que elijas. Ejemplo: Nivel 1 BANO + Nivel 3 TOALLA + Proveedor Espalma = solo las toallas de Espalma; sumando «La descripción dice: set» quedan solo los sets. Dentro de una misma variable alcanza con una (Nivel 3 TOALLA o BATA). Los niveles van de lo general a lo particular: Nivel 1 = grupo (BANO), Nivel 2 = categoría (BLANQUERIA), Nivel 3 = clasificación (TOALLA). Cada lista muestra solo lo que existe dentro de lo ya elegido: eligiendo Nivel 1 BANO, Nivel 2 muestra solo lo de baño; eligiendo además Nivel 2 BLANQUERIA, Nivel 3 muestra solo lo de blanquería (y lo mismo proveedor, material, origen, etc.), con cuántos artículos tiene cada opción. Al tocar la casilla se despliega la lista completa (se recorre con la ruedita o con las flechas y Enter) y escribiendo un pedazo se filtra, sin importar tildes ni mayúsculas (por ejemplo «espalma»). Si algo elegido queda afuera de lo demás (por ejemplo un Nivel 2 que no es de ese Nivel 1), aparece tachado. Arriba se ve al instante cuántos artículos del catálogo entran con esa combinación y algunos de ejemplo (pasando el mouse, más).', 'La ficha está dividida en secciones de colores: Nombre y tipo, Cómo funciona, A qué artículos, Cuándo, y Dónde y estado.', 'Los íconos de cada renglón: pausar o reactivar (la promo queda guardada pero no se aplica), duplicar (arma una nueva con esos datos, para no cargar todo de nuevo) y dar de baja.', 'Para quien necesita autorización, al guardar se abre el pedido de autorización (cámara, celular o clave) como en el resto del POS.'] },
    { icon: '🎁', titulo: 'Gift cards de la web (claudiaadorno.com)', desc: 'Cuando un cliente compra una gift card en la web (GIFTCARD1 a GIFTCARD6), Familia García (Andrea Farías, comex@claudiaadorno.com) la emite en el sistema de la web con un código: el número de pedido + GC + el tipo, por ejemplo 1012555GC4. El POS la maneja sola: al tocar «Pago verificado» en Online, le manda un mail a Andrea desde claudiaadornosrl@gmail.com pidiéndole que la emita y que responda ese mismo mail con el código. Cuando ella responde, el servidor lee la respuesta, carga el código como gift card (aparece en Vales con 🌐 Gift card web) y emite la factura del pedido con el código en el renglón («Gift card web · código …»). Hasta que llega el código, ese pedido no se factura (dice «código pedido a Andrea»). Se puede usar en la web y en los locales: si se usa en la web, el robot ve el cupón en el pedido y le descuenta el saldo solo; si se usa en un local (se cobra como cualquier gift card: se tipea o escanea el código en el renglón Gift card / vale), al emitir le sale un mail automático a Andrea con lo que se usó y el saldo que queda, para que la desactive o la deje en ese saldo en la web. En modo prueba los mails van a la casilla de prueba y no a Andrea.',
      pasos: ['Online → pastilla «🎁 Gift cards web»: todas las compras de gift cards de la web con su código, el saldo, dónde se usó (web o local) y en qué está el pedido del código a Andrea.', 'Si Andrea mandó el código por otro lado, o su respuesta no se entendió («respondió sin código»), tocá «Asociar» y escribí el código y el importe: queda cargada y, si el pago ya estaba verificado, sale la factura con el código.', 'En la caja: Gift card / vale → escribí el código de la web (por ejemplo 1012555GC4). Si ya se usó entero en la web, avisa en qué pedido.', 'Los pedidos cancelados en la web no llevan gift card.'] },
    { icon: '📊', titulo: 'Tablas tipo Excel (títulos fijos, renglones alternados, ordenar, filtrar, ocultar y ancho de columnas)', desc: 'Desde el 19-nov todas las tablas de información del POS (comprobantes, remitos, pedidos, vales, promociones, online, caja, movimientos…) funcionan igual que en Excel, y igual que en los demás módulos del sistema. Títulos fijos: al bajar por una tabla larga, la fila de títulos queda siempre arriba, así se sabe qué es cada columna. Renglones alternados: las filas se pintan una sí y una no para leerlas más fácil, y la fila que está bajo el mouse se resalta. Ordenar: tocar el título de una columna ordena de menor a mayor; tocarlo de nuevo, de mayor a menor; una tercera vez, vuelve al orden original. Las fechas se ordenan como fechas y los importes como números; el detalle desplegado de un renglón se mueve con su renglón y el renglón de Total queda abajo. Filtrar: el embudito al lado de cada título abre un menú para buscar dentro de esa columna, elegir qué valores mostrar (como los filtros de Excel) o poner un «desde/hasta» en fechas e importes. Arriba de la tabla aparece «Mostrando X de Y» con el botón «Quitar filtros» (el total no se recalcula con el filtro). Ocultar columnas: en el mismo menú, «Ocultar columna». Para volver a verlas: «Mostrar» en la barrita de arriba de la tabla, o «Columnas» en el menú de cualquier título. Las columnas ocultas se recuerdan en esa computadora. Agrandar o achicar columnas: arrastrar el borde derecho del título. Doble clic en ese borde (o «Anchos automáticos» en el menú) vuelve al ancho normal. Los anchos también se recuerdan en esa computadora. Los filtros y el orden duran mientras la página esté abierta; al recargarla, la tabla vuelve a mostrarse completa. Excepciones del POS: el ticket que se está armando, los comprobantes impresos o en vista previa y la seña no cambian. Las planillas donde se escriben cantidades o precios (Qué falta, Mínimos, la ficha del pedido, la lista de Etiquetas…) tienen los títulos fijos y los renglones alternados, pero no se reordenan ni se filtran, para no mezclar lo que se está cargando; «Qué falta» además conserva sus colores por proveedor y por juego. Las columnas ocultas y los anchos que se habían guardado con la versión anterior del POS no pasan: hay que volver a ocultarlas o acomodarlas una vez.',
      pasos: ['Tocá el título de una columna para ordenar por ella (▲ ▼; la tercera vez vuelve como venía).', 'Tocá el embudito para filtrar: buscá, tildá los valores o poné desde/hasta.', 'Para volver a ver todo: «Quitar filtros» arriba de la tabla.', 'Ancho de una columna: arrastrá el borde derecho de su título (doble clic: ancho automático).', 'Ocultar una columna: embudito → «Ocultar columna». Para que vuelva: «Mostrar» arriba de la tabla, o «Columnas» en el embudito.'] },
    { icon: '🌐', titulo: 'Online (venta de la tienda web)', desc: 'Solo lo ven Oficina, Administrativa y los admin. Muestra los pedidos de www.claudiaadorno.com de las dos empresas (Claudia Adorno y Familia García): un robot del servidor los baja del panel de la web cada 5 minutos, con el cliente, los artículos, el envío, el pago y la luz del pedido (azul Recibido, amarillo En proceso, verde Terminado, rojo Cancelado).',
      pasos: ['Arriba van las dos tiendas: claudiaadorno.com y atelier.claudiaadorno.com (la del Atelier todavía no está operativa: queda preparada y vacía hasta que arranque).', 'Cada renglón: número y fecha corta (29/10 17:14), cliente, empresa (CA = Claudia Adorno, FGR = Familia García Regueira), total, la luz y tres columnas que siguen el circuito del pedido: Pago, Facturación y Envío.', 'Pago: el medio (MP o Transf.) y si está «a verificar» (botón «Pago verificado») o «✓ verificado» (pasando el mouse se ve quién y cuándo). «Pago verificado» deja el pago anotado (con el número de operación si se pone), pasa el pedido a amarillo en la web y, si es de Claudia Adorno, emite la factura en el mismo momento. Los de Familia García dicen «lo controla FGR».', 'Facturación: la factura asociada (tocándola se abre) con su estado (esperando CAE, mail enviado) y las notas de crédito que tenga; si no tiene factura y es de Claudia Adorno, el botón «Facturar» la emite ya (si una factura no salió, dice por qué y se reintenta con «Facturar»). «NC parcial»: cuando falta mercadería, se elige cuántos de cada artículo faltaron y sale la nota de crédito por eso (mismo precio de la factura, se le manda al cliente por mail); la plata se devuelve a mano en Mercado Pago o por transferencia. No deja devolver más de lo facturado.', 'Envío: domicilio, sucursal OCA o retira, y el número de seguimiento de OCA si lo tiene (más adelante el estado del envío de OCA va a aparecer solo).', 'Tocando el renglón se despliega abajo el resumen del pedido (artículos, envío y seguimiento, contacto, cuántas compras hizo en la web y el pago); tocándolo de nuevo se cierra. En el resumen (y en la ficha) el mail y el celular del cliente son links: el mail abre un correo nuevo con el asunto «Tu pedido web …» y el celular abre WhatsApp (la app o la web, según cómo esté configurada esa compu) con un saludo ya escrito. El número abre la ficha completa.', '«Correr el robot» (en claudiaadorno.com): le pide al robot del servidor que lea la web ya, sin esperar la vuelta de cada 5 minutos; al lado dice «el robot está leyendo la web…» y, cuando termina, cuántos pedidos y clientes nuevos trajo. Si el robot no responde en 3 minutos avisa que puede no estar andando.', 'Los clientes: el robot guarda los datos de cada cliente que compra en la web, de Claudia Adorno y de Familia García (sin la clave de la web), con cuántas compras hizo y cuánto, y los cruza con la ficha del CRM por DNI o mail; en la ficha del CRM solo completa lo que estaba vacío (celular, mail, cumpleaños).', 'Buscador (número de pedido, cliente, mail, DNI o CUIT), la empresa y el estado; «Para facturar» deja solo los de Claudia Adorno que todavía no tienen factura. A la derecha dice hace cuánto leyó el robot la web (en rojo si pasaron más de 20 minutos).', 'Tocando el número se abre el pedido: artículos, envío (y seguimiento), totales y el pago.', '«Pago verificado» (solo pedidos de Claudia Adorno): cuando el pago está en Mercado Pago o llegó la transferencia, se toca, se puede poner el número de operación, y el POS emite solo la factura desde Oficina (A si el pedido es «Factura A» con CUIT, B si es consumidor final con DNI) con los mismos artículos y precios de la web y el envío; da de alta al cliente si no existía y la factura se manda al mail del pedido cuando tiene el CAE. El pedido pasa a amarillo en la web para que lo preparen (lo cambia el robot en la vuelta siguiente; mientras tanto dice «pasa a en proceso»). No se puede facturar dos veces el mismo pedido. Mientras el POS esté en modo prueba, la factura sale de prueba (no va a ARCA y el mail va a la casilla de prueba) y la luz de la web no se toca.', 'Si falta mercadería, se hace la nota de crédito parcial desde la factura, como siempre (Comprobantes → la factura → nota de crédito).', 'Los pedidos que ya tienen la factura cargada en la web (hecha en el Dragon) dicen «facturado» con su número y no se vuelven a facturar.', 'Los pedidos de Familia García solo se ven (con sus datos): los factura Familia García por su lado.', 'Un pedido con promoción o gift card de la web dice «facturar a mano»: se factura desde Vender.', 'Los pagos se registran como «Mercado Pago (tienda web)» o «Transferencia (tienda web)»; esos medios no aparecen en Vender.', 'Próximo paso: cuando los avisos de pago de Mercado Pago lleguen a una casilla nuestra, el robot va a tocar «Pago verificado» solo.'] },
    { icon: '💰', titulo: 'Caja', desc: 'Lo cobrado en el día por medio de pago, con totales de facturado y de facturas manuales. Las notas de crédito restan y los anulados no cuentan.',
      pasos: ['Cambiá el día arriba para ver otro.', 'Sirve para el cierre: tiene que coincidir con lo que marca la planilla de Ventas.'] },
    { icon: '⚙', titulo: 'Ajustes (solo admin)', desc: 'Puntos de venta por local (fiscal y manual) y qué medios de pago se ofrecen.',
      pasos: ['Puntos de venta fiscales del POS en ARCA: 0033 Alcorta, 0034 Unicenter, 0035 Oficina; si se cambia el número la numeración sigue sola desde 1.', 'Un medio de pago apagado deja de aparecer al cobrar; "pide referencia" obliga a cargar el número de cupón.', 'Tope de ARCA para identificar al consumidor final: se muestra con la fecha de la última lectura; no se carga a mano, lo relee el servicio del CAE una vez por mes en la página de ARCA y avisa acá si no pudo.'] },
  ];
}

function abrirManual() {
  if (document.getElementById('manual-overlay')) return;
  const items = _manualSecciones();
  const ov = document.createElement('div');
  ov.id = 'manual-overlay';
  ov.innerHTML = `
    <div class="m-box">
      <div class="m-head">
        <span style="font-size:22px;">📖</span>
        <div style="flex:1;">
          <div style="font-weight:700;font-size:16px;">Manual · POS</div>
          <div style="font-size:12px;opacity:.85;">Guía rápida de cada herramienta del módulo</div>
        </div>
        <button class="m-close" onclick="cerrarManual()">✕</button>
      </div>
      ${items.map((s, i) => `
        <div class="m-sec">
          <div class="m-tit">${s.icon} ${i + 1}. ${_mEsc(s.titulo)}</div>
          <div class="m-desc">${_mEsc(s.desc)}</div>
          ${(s.pasos || []).length ? `<ul class="m-pasos">${s.pasos.map(p => `<li>${_mEsc(p)}</li>`).join('')}</ul>` : ''}
        </div>`).join('')}
      <div class="m-foot">💡 Este manual se actualiza junto con el sistema. ¿Falta algo o no funciona? Avisale a JP.</div>
    </div>`;
  document.body.appendChild(ov);
  _manualLupa(ov);
  document.body.style.overflow = 'hidden';
}

function cerrarManual() {
  const ov = document.getElementById('manual-overlay');
  if (ov) ov.remove();
  document.body.style.overflow = '';
}
document.addEventListener('keydown', e => { if (e.key === 'Escape') cerrarManual(); });

(function _manualInit() {
  const css = document.createElement('style');
  css.textContent = `
    #manual-overlay{position:fixed;inset:0;background:rgba(15,23,42,.55);z-index:9999;display:flex;align-items:flex-start;justify-content:center;padding:20px 12px;overflow-y:auto;-webkit-overflow-scrolling:touch;}
    #manual-overlay .m-box{background:#f8fafc;border-radius:14px;max-width:760px;width:100%;padding-bottom:6px;box-shadow:0 20px 60px rgba(0,0,0,.3);}
    #manual-overlay .m-head{position:sticky;top:0;background:#0e7490;color:#fff;padding:14px 18px;border-radius:14px 14px 0 0;display:flex;align-items:center;gap:10px;z-index:1;}
    #manual-overlay .m-close{background:rgba(255,255,255,.18);border:none;color:#fff;font-size:16px;border-radius:8px;padding:6px 11px;cursor:pointer;}
    #manual-overlay .m-sec{background:#fff;border:1px solid #e2e8f0;border-left:4px solid #0e7490;border-radius:10px;margin:14px 14px 0;padding:14px 18px;}
    #manual-overlay .m-tit{font-weight:700;font-size:15px;margin-bottom:4px;color:#155e75;}
    #manual-overlay .m-desc{font-size:13px;color:#475569;margin-bottom:8px;}
    #manual-overlay .m-pasos{margin:0 0 2px 18px;padding:0;font-size:13px;line-height:1.65;color:#334155;}
    #manual-overlay .m-pasos li{margin-bottom:4px;}
    #manual-overlay .m-foot{margin:16px 14px 12px;background:#cffafe;border-left:4px solid #0891b2;border-radius:8px;padding:11px 14px;font-size:12.5px;color:#155e75;}`;
  document.head.appendChild(css);

})();

// ── 🔍 Lupa del manual (29-sep, pedido Contreras): busca por palabra, sin tildes ni mayúsculas.
//    Deja solo las secciones que la contienen, dentro de ellas los pasos que la contienen,
//    y resalta la palabra. Mismo bloque en todos los módulos (el de RRHH usa _mLupaFiltrar).
function _mLupaNorm(s){ return String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase(); }
function _mLupaMarcar(el, q){
  const nodos = [], w = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
  while (w.nextNode()) nodos.push(w.currentNode);
  nodos.forEach(n => {
    const t = n.nodeValue; let norm = '', mapa = [];
    for (let i = 0; i < t.length; i++){ const c = _mLupaNorm(t[i]); for (let k = 0; k < c.length; k++){ norm += c[k]; mapa.push(i); } }
    let desde = 0, pos, frag = null, ult = 0;
    while (q && (pos = norm.indexOf(q, desde)) >= 0){
      frag = frag || document.createDocumentFragment();
      const a = mapa[pos], b = mapa[pos + q.length - 1] + 1;
      if (a > ult) frag.appendChild(document.createTextNode(t.slice(ult, a)));
      const m = document.createElement('mark'); m.textContent = t.slice(a, b);
      m.style.cssText = 'background:#fde047;color:inherit;padding:0 1px;border-radius:3px'; frag.appendChild(m);
      ult = b; desde = pos + q.length;
    }
    if (frag){ if (ult < t.length) frag.appendChild(document.createTextNode(t.slice(ult))); n.parentNode.replaceChild(frag, n); }
  });
}
function _mLupaFiltrar(cont, selSec, texto, info){
  if (!cont) return;
  const q = _mLupaNorm(String(texto || '').trim());
  let vistas = 0;
  cont.querySelectorAll(selSec).forEach(sec => {
    if (sec.dataset.mOrig == null) sec.dataset.mOrig = sec.innerHTML; else sec.innerHTML = sec.dataset.mOrig;
    if (!q){ sec.style.display = ''; return; }
    const lis = [...sec.querySelectorAll('li')];
    const enLis = lis.filter(li => _mLupaNorm(li.textContent).includes(q));
    const hay = _mLupaNorm(sec.textContent).includes(q);
    sec.style.display = hay ? '' : 'none';
    if (!hay) return;
    vistas++;
    if (enLis.length) lis.forEach(li => { if (!enLis.includes(li)) li.style.display = 'none'; });
    _mLupaMarcar(sec, q);
  });
  if (info) info.textContent = !q ? '' : vistas ? `${vistas} ${vistas === 1 ? 'sección' : 'secciones'} con «${String(texto).trim()}»` : `No encontré «${String(texto).trim()}» en el manual.`;
  const primera = q && cont.querySelector('mark');
  if (primera) primera.scrollIntoView({block: 'center', behavior: 'smooth'});
}
function _manualLupa(ov){
  const head = ov && ov.querySelector('.m-head'); if (!head) return;
  head.style.flexWrap = 'wrap';
  const box = document.createElement('div');
  box.style.cssText = 'flex-basis:100%;display:flex;gap:8px;align-items:center;margin-top:8px';
  box.innerHTML = '<input type="search" placeholder="🔍 Buscar en el manual (por ej.: equivalencias, remito, echeq)…" '
    + 'style="flex:1;min-width:0;padding:8px 11px;border-radius:9px;border:none;font-size:14px;color:#0f172a;font-family:inherit">'
    + '<span class="m-lupa-info" style="font-size:12px;opacity:.9;white-space:nowrap"></span>';
  head.appendChild(box);
  const inp = box.querySelector('input'), info = box.querySelector('.m-lupa-info');
  let t = null;
  inp.addEventListener('input', () => { clearTimeout(t); t = setTimeout(() => _mLupaFiltrar(ov, '.m-sec', inp.value, info), 250); });
  inp.addEventListener('keydown', e => { if (e.key === 'Escape' && inp.value){ e.stopPropagation(); inp.value = ''; _mLupaFiltrar(ov, '.m-sec', '', info); } });
  setTimeout(() => inp.focus(), 50);
}
